let pendingSubsections=null;
let refreshDisconnected = false;
let factsDirty=false, editorDirty=false, report=null, loadedVersion=null, currentChapter=0, uploadBusy=false, view='materials';
let materialsPlan=null, chapterPrompts={};
let preflightApproved=false, preflightBusy=false;
const dirtyFileForms=new Set(), dirtyAssetForms=new Set();

const selectedFileIds = new Set();
let deletingFiles = false;
const fileBatch = el('div', undefined, 'file-batch hidden');
const fileSelection = el('span', '', 'muted');
fileSelection.setAttribute('aria-live', 'polite');
const deleteSelectedFiles = button('删除所选', async () => {
  if (!current || current.busy || uploadBusy || deletingFiles || !selectedFileIds.size) return;
  if (factsDirty || editorDirty || dirtyFileForms.size || dirtyAssetForms.size) {
    throw new Error('请先保存未提交的项目信息、草稿或资料设置，再删除文件');
  }
  const files = current.files.filter(file => selectedFileIds.has(file.id));
  if (!files.length) return;
  const list = files.slice(0, 6).map(file => '• ' + file.name).join('\n');
  const more = files.length > 6 ? '\n…' : '';
  if (!confirm('删除选中的 ' + files.length + ' 份项目资料？\n\n' + list + more +
    '\n\n文件将移出项目列表，本地保留恢复副本。历史报告仍可查看。')) return;
  deletingFiles = true;
  updateFileBatch(current);
  try {
    const result = await post(endpoint('delete-files'), {ids: files.map(file => file.id)});
    selectedFileIds.clear();
    await refresh();
    notify(result.message);
  } finally {
    deletingFiles = false;
    if (current) updateFileBatch(current);
  }
}, 'secondary delete-selected-files');
deleteSelectedFiles.disabled = true;
fileBatch.append(fileSelection, deleteSelectedFiles);
$('#files').before(fileBatch);

function fileSelectionBox(file) {
  const box = el('input', undefined, 'file-selection-box');
  box.type = 'checkbox';
  box.dataset.fileId=file.id;
  box.setAttribute('aria-label', '选择文件：' + file.name);
  box.checked = selectedFileIds.has(file.id);
  box.onchange = () => {
    if (box.checked) selectedFileIds.add(file.id);
    else selectedFileIds.delete(file.id);
    updateFileBatch(current);
  };
  return box;
}

function updateFileBatch(project) {
  const currentIds = new Set(project.files.map(file => file.id));
  for (const id of selectedFileIds) if (!currentIds.has(id)) selectedFileIds.delete(id);
  const blocked = project.busy || uploadBusy || deletingFiles;
  fileBatch.classList.toggle('hidden', !currentIds.size);
  fileSelection.textContent = selectedFileIds.size ? '已选择 ' + selectedFileIds.size + ' 份文件' : '';
  deleteSelectedFiles.disabled = blocked || !selectedFileIds.size;
  deleteSelectedFiles.textContent = deletingFiles ? '删除中…' : '删除所选';
  for (const box of $('#files').querySelectorAll('.file-selection-box')) box.disabled = blocked;
}
let toastTimer;
function notify(text){$('#toast').textContent=text;$('#toast').classList.remove('hidden');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.add('hidden'),7000);}
function el(tag,text,className){const node=document.createElement(tag);if(text!==undefined)node.textContent=text;if(className)node.className=className;return node;}
async function api(path,options={}){const response=await fetch(path,options);let data;try{data=await response.json();}catch{throw new Error('服务返回异常，请刷新页面或重新启动工作台');}if(response.status===401){$('#login').classList.remove('hidden');throw new Error(data.error||'请登录');}if(!response.ok)throw new Error(data.error||'请求失败');return data;}
const post=(path,data={})=>{const action=path.split('/').pop();if(selected&&path.startsWith('/api/projects/'+selected+'/')&&['insert-source-image','remove-source-image','generate','edit','reuse-source-table','outline-edit','save-working','subsection-approval','chapter-approval','chapter-order','assembly-check','assemble'].includes(action)){data={...data,working_revision:current?.working_revision||0};if(['insert-source-image','remove-source-image','generate','edit','reuse-source-table','outline-edit'].includes(action))data.defer_version=true;}return api(path,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify(data)});};
const endpoint=action=>`/api/projects/${selected}/${action}`;
const selectedModel=()=>$('#model-select').value;
function button(text,fn,style='secondary'){const b=el('button',text,style);b.type='button';b.onclick=async()=>{try{await fn();}catch(error){notify(error.message);}};return b;}
function download(name,label,version){const a=el('a',label||name);a.href=endpoint('download/'+name)+(version?'?version='+encodeURIComponent(version):'');a.download=name;if(name==='report.docx'&&!version)a.onclick=async event=>{if(editorDirty){event.preventDefault();try{await saveSection();const fresh=el('a');fresh.href=endpoint('download/report.docx');fresh.download='report.docx';document.body.append(fresh);fresh.click();fresh.remove();}catch(error){notify(error.message);}}};return a;}
function showView(name){view=name;document.querySelectorAll('[data-view]').forEach(b=>{const active=b.dataset.view===name;b.classList.toggle('active',active);b.setAttribute('aria-selected',String(active));});document.querySelectorAll('.view-panel').forEach(p=>p.classList.toggle('hidden',p.id!=='view-'+name));}
for(const b of document.querySelectorAll('[data-view]'))b.onclick=()=>{showView(b.dataset.view);if(b.dataset.view==='knowledge')loadKnowledge().catch(error=>notify(error.message));};
for(const b of document.querySelectorAll('[data-close]'))b.onclick=()=>$('#'+b.dataset.close).close();
