function renderFacts(fields){$('#facts').replaceChildren();if(!fields.length){$('#facts').className='empty-small';$('#facts').textContent='读取资料后会显示提取候选；已有项目的手工填写内容将保留。';return;}$('#facts').className='';for(const field of fields){const row=el('div',undefined,'fact');row.dataset.key=field.key;const label=el('label',field.label);label.htmlFor='fact-'+field.key;const content=el('div');const input=el('input');input.type='text';input.id='fact-'+field.key;input.value=field.value;input.maxLength=2000;input.placeholder='未提取，请核对原资料后填写';input.disabled=current.busy;const check=el('input');check.type='checkbox';check.checked=field.confirmed;check.disabled=current.busy;check.onchange=()=>factsDirty=true;input.oninput=()=>{factsDirty=true;check.checked=false;};content.append(input);if(field.conflict){const select=el('select');select.setAttribute('aria-label',field.label+'候选值');select.append(el('option','存在多个候选，请对照资料选择'));for(const candidate of [...new Map(field.candidates.map(c=>[c.value,c])).values()]){const o=el('option',candidate.value);o.value=candidate.value;select.append(o);}select.disabled=current.busy;select.onchange=()=>{if(select.selectedIndex){input.value=select.value;check.checked=false;factsDirty=true;}};content.append(select);}const sources=field.candidates?.slice(0,2).map(c=>c.source+' '+c.locator).join('；');content.append(el('small',field.changed?'新增资料出现不同信息，请重新核对。':sources||'人工填写内容将保留，并标记为人工核对。',field.changed||field.conflict?'conflict':''));const confirmation=el('label',undefined,'confirmation');confirmation.append(check,document.createTextNode('已核对'));row.append(label,content,confirmation);$('#facts').append(row);}}
