async function upload(files,role){if(!selected||current.busy||uploadBusy||!files.length)return;try{if(factsDirty)await saveFacts();if(editorDirty)await saveSection();uploadBusy=true;render(current);$('#upload-results').replaceChildren();let added=0;for(let i=0;i<files.length;i++){const file=files[i];const line=el('p',`${i+1}/${files.length} · ${file.name}：上传中`);$('#upload-results').append(line);try{if(file.size>80000000)throw new Error('文件超过 80 MB');const result=await api(endpoint('upload')+'?name='+encodeURIComponent(file.name)+'&role='+encodeURIComponent(role||$('#upload-role').value),{method:'POST',headers:{'Content-Type':'application/octet-stream'},body:file});line.textContent=file.name+'：'+result.message;if(!result.skipped&&!result.duplicate)added++;}catch(error){line.textContent=file.name+'：'+error.message;line.classList.add('error');}}notify(added?'新增 '+added+' 份资料，已有信息和草稿已保留。请读取更新。':'未新增文件，请查看逐项导入结果');}catch(error){notify(error.message);}finally{uploadBusy=false;for(const id of ['file-input','folder-input','figure-input'])$('#'+id).value='';await refresh();}}
$('#analyze').onclick=async()=>{try{if(factsDirty)await saveFacts();if($('#ai-extract').checked&&!selectedModel()){openModelSettings();return;}await post(endpoint('analyze'),{ai_extract:$('#ai-extract').checked,model_id:selectedModel()});await refresh();}catch(error){notify(error.message);}};
function renderAssets(files){$('#asset-list').replaceChildren();for(const f of files.filter(f=>f.active!==false&&(f.role==='figure'||f.renderable&&f.role==='attachment'||/\.(dwg|dxf|svg)$/i.test(f.name)))){const card=el('div',undefined,'asset-card');card.addEventListener('input',()=>dirtyAssetForms.add(f.id));card.addEventListener('change',()=>dirtyAssetForms.add(f.id));card.append(el('strong',f.name),el('small',f.status||''));const label=el('label','报告图题');const caption=el('input');caption.value=f.caption||f.name;caption.maxLength=160;label.append(caption);card.append(label);let pages=null;if(/\.pdf$/i.test(f.name)){const p=el('label','使用页码，例如 1,3-5');pages=el('input');pages.value=f.pages||'1';p.append(pages);card.append(p);}const placeLabel=el('label','插入位置');const place=el('select');place.setAttribute('aria-label',f.name+'插入位置');const appendOption=el('option','报告文末 · 项目图件');appendOption.value='';place.append(appendOption);const saved=f.figure_resolved_placement||f.figure_placement||{};const savedValue=saved.section_id?JSON.stringify({section_id:saved.section_id,paragraph_index:saved.paragraph_index??null}):'';for(const section of report?.sections||[]){const ident=sectionId(section);if(!ident)continue;const option=el('option',section.title+' · 章节末尾');option.value=JSON.stringify({section_id:ident,paragraph_index:null});place.append(option);(section.paragraphs||[]).forEach((paragraph,index)=>{const short=(paragraph.text||'').replace(/\s+/g,' ').slice(0,38);const opt=el('option',section.title+' · 第'+(index+1)+'段后：'+short);opt.value=JSON.stringify({section_id:ident,paragraph_index:index});place.append(opt);});}if(f.figure_placement_warning||(savedValue&&![...place.options].some(o=>o.value===savedValue))){const option=el('option','原位置已失效，请重新选择');option.value='__stale__';place.append(option);place.value='__stale__';}else place.value=savedValue;place.disabled=!f.renderable||current.busy;placeLabel.append(place);card.append(placeLabel);if(f.figure_placement_warning)card.append(el('small',f.figure_placement_warning,'conflict'));if(!report)card.append(el('small','生成草稿后可选择章节或段落；当前可先放在文末。'));const checkLabel=el('label',undefined,'checkbox-label');const check=el('input');check.type='checkbox';check.checked=!!f.include;check.disabled=!f.renderable||current.busy;checkLabel.append(check,document.createTextNode(f.renderable?'放入报告':'需先导出 PDF/图片'));card.append(checkLabel);const actions=el('div',undefined,'asset-actions');if(f.renderable)actions.append(button('预览',async()=>{let page=1;if(pages){const first=pages.value.match(/\d+/);page=first?Number(first[0]):1;}$('#image-preview').src=endpoint('files/'+f.id+'/preview')+'?page='+page;$('#image-dialog').showModal();}));actions.append(button('保存图件设置',async()=>{if(place.value==='__stale__')throw Error('原插入位置已失效，请重新选择');await post(endpoint('files'),{id:f.id,caption:caption.value,include:check.checked,figure_placement:place.value?JSON.parse(place.value):{},figure_placement_base_version:current.report_version||'',...(pages?{pages:pages.value}:{})});dirtyAssetForms.delete(f.id);notify('已保存，下一次生成或保存草稿时更新导出');await refresh();}));const original=el('a','下载原文件');original.href=endpoint('files/'+f.id+'/download');actions.append(original);card.append(actions);$('#asset-list').append(card);}}
$('#image-preview').onerror=()=>notify('图件无法预览，请检查页码、依赖和原文件格式');
$('#make-flow').onclick=async()=>{try{const result=await post(endpoint('flow'),{steps:$('#flow-steps').value.split('\n').map(s=>s.trim()).filter(Boolean)});notify(result.message);await refresh();}catch(error){notify(error.message);}};
$('#find-location').onclick=async()=>{try{const result=await post(endpoint('geocode'),{address:$('#map-address').value});$('#map-candidates').replaceChildren();if(!result.candidates.length)notify('没有匹配位置，请补充详细地址');for(const c of result.candidates)$('#map-candidates').append(button(c.address+' · '+c.level+' · 确认并取图',async()=>{const result=await post(endpoint('map'),c);notify(result.message);await refresh();}));}catch(error){notify(error.message);}};
function renderModels(preferred){const previous=preferred||$('#model-select').value||modelSettings.default_model_id;$('#model-select').replaceChildren();if(!modelSettings.models.length){const o=el('option','请点击“配置或添加模型”');o.value='';$('#model-select').append(o);}for(const model of modelSettings.models){const o=el('option',model.name+' · '+model.model);o.value=model.id;$('#model-select').append(o);}if(modelSettings.models.some(m=>m.id===previous))$('#model-select').value=previous;$('#header-model').textContent=modelSettings.models.length?'模型已配置 · 可切换':'配置编写模型';}
async function loadSettings(preferred){modelSettings=await api('/api/settings');renderModels(preferred);}
function openModelSettings(){if(!modelSettings){notify('模型设置正在加载，请稍后再试');return;}const select=$('#saved-model');select.replaceChildren();const fresh=el('option','＋ 添加新模型');fresh.value='';select.append(fresh);for(const m of modelSettings.models){const o=el('option',m.name+' · '+m.model);o.value=m.id;select.append(o);}$('#provider').replaceChildren();for(const p of modelSettings.presets){const o=el('option',p.name);o.value=p.id;$('#provider').append(o);}select.value=selectedModel()||'';fillModel(select.value);$('#model-dialog').showModal();}
for(const id of ['open-models','header-model','configure-model'])$('#'+id).onclick=openModelSettings;
function fillModel(id){const model=modelSettings.models.find(m=>m.id===id);$('#provider').value=model?.provider||'deepseek';$('#model-name').value=model?.name||'';$('#base-url').value=model?.base_url||modelSettings.presets.find(p=>p.id===$('#provider').value)?.base_url||'';$('#api-key').value='';$('#api-key').placeholder=model?.key_saved?'密钥已保存，留空保持；更换地址需重新输入':'填写供应商密钥；本机模型可留空';$('#model-id').value=model?.model||'';$('#json-mode').checked=model?.json_mode!==false;$('#available-models').replaceChildren();$('#model-result').textContent='';providerHint();}
$('#saved-model').onchange=()=>fillModel($('#saved-model').value);
function providerHint(){$('#provider-hint').textContent=$('#provider').value==='qwen'?'默认北京区域地址；也可填写公司工作空间地址。API Key 与地域、计费方式须匹配。':$('#provider').value==='ollama'?'需要电脑已运行 Ollama 并安装模型。模型 ID 可从服务获取。':'填写 API 基础地址，不要包含 /chat/completions；模型 ID 可从服务获取或手工填写。';}
$('#provider').onchange=()=>{const p=modelSettings.presets.find(p=>p.id===$('#provider').value);$('#base-url').value=p?.base_url||'';$('#api-key').value='';$('#model-id').value='';providerHint();};
function modelInput(){return {id:$('#saved-model').value,name:$('#model-name').value,provider:$('#provider').value,base_url:$('#base-url').value,api_key:$('#api-key').value,model:$('#model-id').value,json_mode:$('#json-mode').checked};}
async function modelAction(action){const output=$('#model-result');output.classList.remove('error');output.textContent=action==='models'?'正在获取模型列表…':'正在测试接口和结构化输出…';for(const id of ['fetch-models','test-model'])$('#'+id).disabled=true;try{const result=await post('/api/settings/'+action,modelInput());if(action==='models'){$('#available-models').replaceChildren();for(const id of result.models){const o=el('option');o.value=id;$('#available-models').append(o);}if(!$('#model-id').value&&result.models.length)$('#model-id').value=result.models[0];output.textContent='获取到 '+result.models.length+' 个模型，可在“模型 ID”中选择。';}else output.textContent=result.message;}catch(error){output.classList.add('error');output.textContent=error.message+(action==='models'?'；供应商可能不提供兼容模型列表，请直接填写控制台提供的模型 ID。':'');}finally{for(const id of ['fetch-models','test-model'])$('#'+id).disabled=false;}}
$('#fetch-models').onclick=()=>modelAction('models');$('#test-model').onclick=()=>modelAction('test');
$('#model-form').onsubmit=async e=>{e.preventDefault();try{const result=await post('/api/settings/model',modelInput());$('#api-key').value='';await loadSettings(result.id);$('#model-dialog').close();notify('模型配置已保存并选用。可先测试连接，再编写正文。');}catch(error){$('#model-result').textContent=error.message;$('#model-result').classList.add('error');}};
$('#generation-scope').onchange=()=>$('#chapter-checks').classList.toggle('hidden',$('#generation-scope').value!=='selected');
for(const radio of document.querySelectorAll('input[name=mode]'))radio.onchange=()=>$('#outline-notice').classList.toggle('hidden',document.querySelector('input[name=mode]:checked').value!=='outline');
function sectionId(section){return section.id||section.title.match(/^\d+/)?.[0]||'';}
function buildChapterChecks(items){if(report&&report.template_sha256!==template?.sha256)items=null;$('#chapter-checks').replaceChildren();const sections=items||template.headings.filter(h=>h.level===1).map(h=>({title:h.text}));for(const section of sections){const label=el('label');const c=el('input');c.type='checkbox';c.value=sectionId(section);c.disabled=!!report?.chapter_workflow?.[c.value]?.locked;label.append(c,document.createTextNode(section.title));$('#chapter-checks').append(label);}$('#chapter-checks').classList.toggle('hidden',$('#generation-scope').value!=='selected');}
async function beginGeneration(){if(dirtyFileForms.size||dirtyAssetForms.size){showView('materials');throw new Error('请先保存资料元数据和图件设置，再生成报告');}const use_llm=document.querySelector('input[name=mode]:checked').value==='llm';if(use_llm&&!selectedModel()){openModelSettings();notify('先保存一个模型配置，即可编写正文');return;}if(editorDirty)await saveSection();const fields=readFacts();const missing=fields.filter(f=>['company','project'].includes(f.key)&&!f.value.trim());if(missing.length){showView('materials');$('#facts-card').scrollIntoView({behavior:'smooth'});throw new Error('请填写：'+missing.map(f=>current.fields.find(x=>x.key===f.key).label).join('、'));}const unchecked=fields.filter(f=>f.value.trim()&&!f.confirmed);if(unchecked.length){$('#unconfirmed-list').replaceChildren();for(const f of unchecked)$('#unconfirmed-list').append(el('li',current.fields.find(x=>x.key===f.key).label+'：'+f.value));$('#review-dialog').showModal();return;}await launchGeneration();}
async function launchGeneration(){await saveFacts();const use_llm=document.querySelector('input[name=mode]:checked').value==='llm';const chosen=[...$('#chapter-checks').querySelectorAll('input:checked')].map(c=>c.value);if($('#generation-scope').value==='selected'&&!chosen.length)throw new Error('请在“本次处理范围”下勾选至少一个要重写的章节');let answers='',answerChapter='';if(materialsPlan){const blocks=[...$('#materials-advisor .material-answer')].map((field,index)=>({item:materialsPlan.requests[index],answer:field.value.trim()})).filter(x=>x.answer);if(blocks.length){answerChapter=materialsPlan.chapter_id;if(!chosen.includes(answerChapter))throw new Error('资料答复属于“'+materialsPlan.chapter+'”，请勾选该章后再生成');answers=blocks.map(x=>'需要补充的事项：'+x.item.ask+'\n用户答复（仍需依据核验）：'+x.answer).join('\n\n');}}const prompt=chosen.length===1?(chapterPrompts[chosen[0]]||''):'';await post(endpoint('generate'),{use_llm,model_id:selectedModel(),instructions:[$('#instructions').value.trim(),prompt].filter(Boolean).join('\n\n'),...(answers?{supplement_answers:answers,supplement_chapter:answerChapter}:{}),...($('#generation-scope').value==='selected'?{chapter_ids:chosen}:{})});await refresh();}
$('#generate').onclick=async()=>{try{pendingSubsections=null;await beginGeneration();}catch(error){notify(error.message);}};
$('#cancel-generation').onclick=async()=>{try{await post(endpoint('cancel'));await refresh();}catch(error){notify(error.message);}};
$('#return-facts').onclick=()=>{$('#review-dialog').close();showView('materials');$('#facts-card').scrollIntoView({behavior:'smooth'});};
$('#confirm-generate').onclick=async()=>{try{confirmFilled();$('#review-dialog').close();await launchGeneration();}catch(error){notify(error.message);}};
async function loadReport(){const result=await api(endpoint('report'));report=result.report;if(report)report._workflow_revision=current.data_revision;loadedVersion=current.report_version;editorDirty=false;$('#editor-content').classList.toggle('hidden',!report);$('#editor-empty').classList.toggle('hidden',!!report);if(!report)return;if(!dirtyAssetForms.size)renderAssets(current.files);currentChapter=Math.min(currentChapter,report.sections.length-1);$('#editor-chapter').replaceChildren();for(let i=0;i<report.sections.length;i++){const o=el('option',report.sections[i].title);o.value=String(i);$('#editor-chapter').append(o);}$('#editor-chapter').value=String(currentChapter);$('#draft-mode').textContent=['outline','evidence_outline'].includes(report.mode)?'编写提纲 · 尚未智能成稿':report.quality_checked?'智能编写 · 已过摘录检查':'旧版草稿 · 待重新编写';renderEditor();$('#downloads').replaceChildren();for(const name of ['report.docx','report.pdf','review.html','report.json'])if(current.downloads.includes(name))$('#downloads').append(download(name,{'report.pdf':'↓ 下载分页 PDF','report.docx':'↓ 导出 Word','review.html':'↓ 核对清单（可阅读）','report.json':'↓ 内容与证据 JSON'}[name]));}
function paragraphRow(item,index){const section=report.sections[currentChapter];const block=el('div',undefined,'paragraph-block');if(index!==null)block.dataset.originalIndex=String(index);const select=el('select');select.setAttribute('aria-label','段落所属标题');for(const heading of [section.title,...section.subheadings]){const o=el('option',heading);o.value=heading;o.selected=heading===(item.heading||section.title);select.append(o);}select.onchange=()=>editorDirty=true;const text=el('textarea');text.value=item.text||'';text.rows=Math.max(3,Math.min(12,Math.ceil(text.value.length/60)));text.oninput=()=>{editorDirty=true;};const actions=el('div',undefined,'paragraph-actions');actions.append(el('small',item.human_edited?'人工修改的段落':'可直接修改，出处独立保留'),button('移除此段',()=>{block.remove();editorDirty=true;$('#editor-content').dispatchEvent(new Event('input',{bubbles:true}));if(typeof drawReadingView==='function')drawReadingView();}));block.append(select,text,actions);return block;}
function renderEditor(){const section=report.sections[currentChapter];$('#paragraph-editor').replaceChildren();section.paragraphs.forEach((p,i)=>$('#paragraph-editor').append(paragraphRow(p,i)));if(!section.paragraphs.length)$('#paragraph-editor').append(el('p','本章还没有正文，可以补充段落，或选择本章让模型编写。','muted'));$('#table-editor').replaceChildren();for(let ti=0;ti<section.tables.length;ti++){const t=section.tables[ti];const box=el('div',undefined,'editor-table');box.dataset.tableIndex=String(ti);box.append(el('h3',t.caption));const table=el('table');for(let ri=-1;ri<t.rows.length;ri++){const tr=el('tr');const row=ri===-1?t.headers:t.rows[ri];for(let ci=0;ci<row.length;ci++){const cell=el(ri===-1?'th':'td');const input=el('textarea');input.value=row[ci];input.dataset.row=String(ri);input.dataset.col=String(ci);input.setAttribute('aria-label',t.caption+(ri===-1?'表头':'第'+(ri+1)+'行')+'第'+(ci+1)+'列');input.oninput=()=>editorDirty=true;cell.append(input);tr.append(cell);}table.append(tr);}box.append(table);box.append(button('＋ 增加一行',()=>{const ri=table.querySelectorAll('tr').length-1;const tr=el('tr');for(let ci=0;ci<t.headers.length;ci++){const td=el('td');const input=el('textarea');input.dataset.row=String(ri);input.dataset.col=String(ci);input.setAttribute('aria-label',t.caption+'新增行第'+(ci+1)+'列');input.oninput=()=>editorDirty=true;td.append(input);tr.append(td);}table.append(tr);editorDirty=true;}));$('#table-editor').append(box);}$('#chapter-review').replaceChildren();for(const t of [...section.missing,...section.review])$('#chapter-review').append(el('li',t));const trace=section.agent_trace||[];$('#agent-trace').replaceChildren();for(const item of trace)$('#agent-trace').append(el('li',item.agent+'：'+item.status));$('#agent-trace-panel').classList.toggle('hidden',!trace.length);}
$('#editor-chapter').onchange=async()=>{const next=Number($('#editor-chapter').value);try{if(editorDirty)await saveSection();currentChapter=next;$('#editor-chapter').value=String(next);renderEditor();}catch(error){$('#editor-chapter').value=String(currentChapter);notify(error.message);}};
$('#add-paragraph').onclick=()=>{if(!report)return;const row=paragraphRow({text:''},null);$('#paragraph-editor').append(row);row.querySelector('textarea').focus();editorDirty=true;};
async function saveSection(){if(!report)return;const section=report.sections[currentChapter];const paragraphs=[...$('#paragraph-editor').querySelectorAll('.paragraph-block')].map(row=>({text:row.querySelector('textarea').value,heading:row.querySelector('select').value,...(row.dataset.originalIndex!==undefined?{original_index:Number(row.dataset.originalIndex)}:{})}));const tables=section.tables.map(t=>({...t,headers:[...t.headers],rows:t.rows.map(r=>[...r])}));for(const box of $('#table-editor').querySelectorAll('.editor-table')){const t=tables[Number(box.dataset.tableIndex)];for(const input of box.querySelectorAll('textarea')){const row=Number(input.dataset.row),col=Number(input.dataset.col);if(row===-1)t.headers[col]=input.value;else{if(!t.rows[row])t.rows[row]=Array(t.headers.length).fill('');t.rows[row][col]=input.value;}}}await post(endpoint('edit'),{base_version:current.report_version,sections:[{title:section.title,paragraphs,tables}]});editorDirty=false;loadedVersion=null;await refresh();notify('修改已暂存编辑区；完成本轮编辑后统一保存版本');}
$('#save-section').onclick=async()=>{try{await saveSection();}catch(error){notify(error.message);}};
function renderHistory(records){$('#history-list').replaceChildren();if(!records.length){$('#history-list').append(el('p','生成第一版后，版本会记录在这里。','empty-small'));return;}for(let i=0;i<records.length;i++){const v=records[i];const row=el('div',undefined,'history-row');const info=el('div');const kind={legacy:'升级前草稿',generation:'生成 / 修订',edit:'手工编辑',restore:'历史恢复',assembly:'最终组稿'}[v.kind]||v.kind;info.append(el('strong',(i===0?'当前 · ':'')+kind),el('p',v.description||'报告版本'),el('small',new Date(v.created_at).toLocaleString()+' · '+(v.model_name||(['outline','evidence_outline'].includes(v.mode)?'编写提纲':'保留版本'))));const actions=el('div',undefined,'history-actions');actions.append(download('report.docx','下载此版 Word',v.id),download('review.html','核对清单',v.id));if(v.pdf_ready)actions.append(download('report.pdf','下载此版 PDF',v.id));if(i>0)actions.append(button('恢复为新版本',async()=>{if(editorDirty)await saveSection();if(!confirm('将此版本恢复为当前草稿？现有版本仍会保留。'))return;await post(endpoint('restore'),{version:v.id,base_version:current.report_version});loadedVersion=null;await refresh();showView('draft');notify('已恢复，所有历史版本均保留');}));row.append(info,actions);$('#history-list').append(row);}}
window.addEventListener('beforeunload',e=>{if(factsDirty||editorDirty){e.preventDefault();e.returnValue='';}});
async function init(){try{service=await api('/api/status');template=await api('/api/template');await loadSettings();buildChapterChecks();$('#pdf-state').textContent=service.pdf_ready?(service.ocr_ready?'PDF 文字不足的页面会尝试本地 OCR，识别结果请对照原件核对。':'文本型 PDF 可读取。请初始化项目环境以启用扫描页 OCR。'):'PDF 依赖未安装，请使用更新后的启动入口。';$('#map-state').textContent=service.map_ready?'输入地址并确认匹配位置后获取地图。':'地图服务未配置，也可直接上传已有位置图。';const projects=await listProjects();const saved=localStorage.getItem('safety-selected');if(projects.length)await selectProject(projects.some(p=>p.id===saved)?saved:projects[0].id);}catch(error){if($('#login').classList.contains('hidden'))notify(error.message);}finally{const splash=$('#splash');splash.classList.add('splash-hidden');setTimeout(()=>splash.remove(),350);}}
const renderEditorBase=renderEditor;
renderEditor=function(){renderEditorBase();if(!report)return;let notice=$('#chapter-generation-warning');if(!notice){notice=el('div',undefined,'inline-notice hidden');notice.id='chapter-generation-warning';$('#paragraph-editor').before(notice);}const section=report.sections[currentChapter];const failure=(report.generation_errors||[]).find(item=>item.title===section.title);if(failure||section.generation_error||section.needs_rewrite||section.generation_status==='not_generated'){notice.textContent=failure?'本章本次调用模型失败，当前显示的是旧版内容，尚未完成本次改写。失败原因：'+failure.error:section.generation_error?'本章仍是未通过检查的旧版内容：'+section.generation_error:section.generation_status==='not_generated'?'本章尚未生成，请在上方选择本章继续逐章编写。':'本章是未通过检查的旧版内容，请单独重写后再导出。';notice.classList.remove('hidden');}else{notice.textContent='';notice.classList.add('hidden');}if(report.mode==='llm'){if(report.status==='partial')$('#draft-mode').textContent='智能编写 · 部分章节失败，可逐章重试';else if(report.status==='in_progress')$('#draft-mode').textContent='逐章编写 · 当前报告尚未完成';else if(report.quality_checked)$('#draft-mode').textContent='智能编写 · 全部章节已通过检查';else $('#draft-mode').textContent='智能编写 · 本次选择章节已保存';}};
init();
const versionTicker=setInterval(()=>{if(service?.version){const badge=$('.header-tags .tag:last-child');if(badge)badge.textContent='v'+service.version;clearInterval(versionTicker);}},50);
const chapterUiStyle=document.createElement('style');chapterUiStyle.textContent='.chapter-structure-actions{display:flex;gap:8px;flex-wrap:wrap;margin-left:auto}.materials-advisor{margin:18px 0;padding:18px;background:#f8faf7;border:1px solid #dfe8df;border-radius:8px}.materials-advisor h3{font-size:14px}.materials-advisor .material-request{margin:12px 0;padding:14px;background:white;border:1px solid #e5ebe5;border-radius:6px}.material-request strong,.material-request small{display:block;line-height:1.8}.material-request p{font-size:12px;line-height:1.8}.material-answer{margin-top:8px;font-size:12px;line-height:1.7}.chapter-structure-actions .danger{background:#fff0ee;color:#963f37}.materials-advisor>small{display:block;line-height:1.8;color:#7a8e81}';document.head.append(chapterUiStyle);

function ensureChapterControls(){if(!report)return;const section=report.sections[currentChapter];const ident=sectionId(section);const toolbar=$('#editor-card .editor-toolbar');if(!$('#rewrite-current')){toolbar.append(button('按本章提示词重写',rewriteCurrentChapter,'primary'));toolbar.append(button('询问本章缺少什么资料',askForMaterials));}let promptBox=$('#chapter-prompt-box');if(!promptBox){promptBox=el('label','本章修改要求（自然语言）','block-label');promptBox.id='chapter-prompt-box';const input=el('textarea');input.id='chapter-prompt';input.rows=3;input.maxLength=4000;input.placeholder='例如：结合新增的总平面图，重写本章选址与周边环境分析；保留已核实数据，缺少的信息列为待补充。';promptBox.append(input);$('#paragraph-editor').before(promptBox);input.oninput=()=>{chapterPrompts[input.dataset.chapterId]=input.value;};}const promptInput=$('#chapter-prompt');promptInput.dataset.chapterId=ident;promptInput.value=chapterPrompts[ident]||'';let panel=$('#materials-advisor');if(!panel){panel=el('section',undefined,'materials-advisor hidden');panel.id='materials-advisor';$('#paragraph-editor').before(panel);}const heading=$('#editor-card .card-heading');if(!$('#chapter-structure-actions')){const actions=el('div',undefined,'chapter-structure-actions');actions.id='chapter-structure-actions';actions.append(button('＋ 新增章节',addCustomChapter));actions.append(button('删除本章',deleteCurrentChapter,'danger'));heading.append(actions);}}
async function rewriteCurrentChapter(){pendingSubsections=null;const section=report.sections[currentChapter];const ident=sectionId(section);$('#generation-scope').value='selected';$('#chapter-checks').classList.remove('hidden');for(const box of $('#chapter-checks').querySelectorAll('input'))box.checked=box.value===ident;if(!chapterPrompts[ident]?.trim())notify('本章提示词为空，将按资料和现有质量缺项重新编写');await beginGeneration();}
async function askForMaterials(){if(!report)return;if(!selectedModel()){openModelSettings();notify('请先配置并选择模型');return;}if(editorDirty)await saveSection();const section=report.sections[currentChapter];const ident=sectionId(section);$('#generation-scope').value='selected';$('#chapter-checks').classList.remove('hidden');for(const box of $('#chapter-checks').querySelectorAll('input'))box.checked=box.value===ident;const panel=$('#materials-advisor');panel.classList.remove('hidden');panel.replaceChildren(el('p','正在根据本章缺项、审阅事项和已关联资料整理清单…','muted'));try{const result=await post(endpoint('materials-plan'),{chapter_id:ident,model_id:selectedModel()});materialsPlan={...result,chapter_id:ident,baseVersion:current.report_version};renderMaterialsPlan();}catch(error){panel.replaceChildren(el('p',error.message,'error'));}}
function renderMaterialsPlan(){const panel=$('#materials-advisor');panel.replaceChildren();panel.append(el('h3','本章资料补充清单 · '+materialsPlan.chapter));if(materialsPlan.note)panel.append(el('p',materialsPlan.note,'muted'));panel.append(el('p',materialsPlan.can_draft_now?'现有材料可以先形成有限草稿；以下补充项可提升完整度。':'建议先处理“必须”项，再重写本章。可上传文件，也可在每项下填写已确认的信息。','muted'));for(const item of materialsPlan.requests){const card=el('article',undefined,'material-request');card.append(el('strong','【'+item.priority+'】'+item.subheading));card.append(el('p',item.ask));card.append(el('small','需要包含：'+item.include));card.append(el('small','用途：'+item.reason));if(item.examples.length)card.append(el('small','可上传：'+item.examples.join('、')));const answer=el('textarea');answer.className='material-answer';answer.dataset.chapterId=materialsPlan.chapter_id;answer.dataset.ask=item.ask;answer.value=savedAnswers.get(item.chapter_id+'\n'+item.ask)||'';answer.rows=2;answer.maxLength=2000;answer.placeholder='如果暂时没有文件，可填写已确认的事实；模型会将其标记为待核实。';answer.setAttribute('aria-label',item.subheading+'补充答复');card.append(answer);panel.append(card);}if(!materialsPlan.requests.length)panel.append(el('p','模型未发现新的资料请求；仍请核对本章待补充与核对事项。','muted'));panel.append(el('small','本清单是模型给出的准备建议，不是法规要求清单。上传资料后请点击“读取新增资料”，再按本章重写。用户填写的答复会作为待核实证据传给模型。','muted'));}
async function addCustomChapter(){const title=prompt('请输入新增章节标题（例如：项目特殊风险补充分析）');if(title===null)return;await post(endpoint('edit'),{base_version:current.report_version,sections:[],add_chapter:title});loadedVersion=null;currentChapter=report.sections.length;await refresh();showView('draft');notify('已新增章节，可补充正文或填写提示词后重写');}
async function deleteCurrentChapter(){const section=report.sections[currentChapter];if(!confirm('确定删除“'+section.title+'”？删除会影响导出的报告结构，并作为新版本保存。'))return;await post(endpoint('edit'),{base_version:current.report_version,sections:[],delete_chapter_ids:[sectionId(section)]});currentChapter=Math.max(0,currentChapter-1);loadedVersion=null;materialsPlan=null;await refresh();notify('章节已删除，历史版本仍可恢复');}
function renderGroundedReview(){
  const section=report?.sections[currentChapter];if(!section)return;
  let box=$('#chapter-grounded-review');
  if(!box){box=el('details',undefined,'evidence-panel');box.id='chapter-grounded-review';$('#agent-trace-panel').after(box);}
  box.replaceChildren();const rows=section.review_records||[];box.classList.toggle('hidden',!rows.length);if(!rows.length)return;
  box.append(el('summary','审稿原句与证据（'+rows.length+' 条）'),el('p','引句核对与模型复核不等于专业审核。以下保留各轮意见及处理结果。','muted'));
  const labels={confirm:'复核确认，触发定向返修',reject:'复核驳回，未触发返修',manual:'待人工核对',unverified:'原句核验未通过',advisory:'文风建议'};
  for(const row of rows){
    const f=row.finding||{};const card=el('div',undefined,'review-card');
    card.append(el('strong','第'+((row.attempt||0)+1)+'轮 · '+(labels[row.status]||'待核对')));
    if(typeof f==='object'){
      card.append(el('p','正文位置：'+(f.target_id||'未提供')),el('p','正文原句：'+(f.draft_quote||'未提供')),el('p','证据 '+(f.evidence_id||'未提供')+' 原句：'+(f.evidence_quote||'未提供')),el('p','所述差异：'+(f.reason||'未提供')),el('p','修改建议：'+(f.suggestion||'未提供')));
    }else card.append(el('p',String(f)));
    card.append(el('p','核验结果：'+(row.reason||'')));box.append(card);
  }
}
function renderSourceReview(){const section=report?.sections[currentChapter];if(!section)return;let box=$('#chapter-source-review');if(!box){box=el('details',undefined,'evidence-panel');box.id='chapter-source-review';$('#agent-trace-panel').after(box);}box.replaceChildren();const rows=section.source_review||[];box.classList.toggle('hidden',!rows.length);if(!rows.length)return;box.append(el('summary','本章资料筛选记录（'+rows.length+' 条）'),el('p','以下是模型提供的用途建议，不代表项目事实或法规有效性已经确认。','muted'));const list=el('ul');for(const row of rows){const label=({use:'可能相关',verify:'待核对',omit:'建议省略'})[row.decision]||'待核对';list.append(el('li',label+' · '+row.id+'：'+row.reason));}box.append(list);}
const renderEditorWithControls=renderEditor;
