const loadReportWithChapterChecks=loadReport;
loadReport=async function(){const selectedIds=new Set([...$('#chapter-checks').querySelectorAll('input:checked')].map(box=>box.value));const scopeValue=$('#generation-scope').value;await loadReportWithChapterChecks();if(report){buildChapterChecks(report.sections);for(const box of $('#chapter-checks').querySelectorAll('input'))box.checked=selectedIds.has(box.value);$('#generation-scope').value=scopeValue;$('#chapter-checks').classList.toggle('hidden',scopeValue!=='selected');if($('#chapter-prompt')){const ident=sectionId(report.sections[currentChapter]);$('#chapter-prompt').dataset.chapterId=ident;$('#chapter-prompt').value=chapterPrompts[ident]||'';}}};
const renderWithChapterHint=render;
render=function(project){renderWithChapterHint(project);let hint=$('#chapter-scope-hint');if(!hint){hint=el('p',undefined,'muted');hint.id='chapter-scope-hint';$('#chapter-checks').after(hint);}hint.textContent=project.has_report?'已有报告默认按章处理。请勾选要重写的章节；全文重写会重新调用模型处理所有章节。':'新项目可先生成一章，再逐章完善。';};
// Preflight every chapter in the requested scope before spending tokens on report drafting.
launchGeneration=async function(){
 if(preflightBusy)return;
 const useLlm=document.querySelector('input[name=mode]:checked').value==='llm';
 const chosen=$('#generation-scope').value==='selected'?[...$('#chapter-checks').querySelectorAll('input:checked')].map(x=>x.value):($('#chapter-checks').querySelectorAll('input').length?[...$('#chapter-checks').querySelectorAll('input')].map(x=>x.value):[]);
 if(chosen.some(id=>report?.chapter_workflow?.[id]?.locked)){if($('#generation-scope').value==='selected')throw new Error('所选章节已锁定，请先解锁');for(let i=chosen.length-1;i>=0;i--)if(report?.chapter_workflow?.[chosen[i]]?.locked)chosen.splice(i,1);}
 if(useLlm&&!preflightApproved){
  if(!selectedModel()){openModelSettings();throw new Error('先保存一个模型配置，即可编写正文');}
  if(!chosen.length)throw new Error('请先选择本次要生成的章节');
  if(current.analysis_dirty)throw new Error('资料已变更，请先在资料页点击“读取新增资料并更新信息”');
  preflightBusy=true;$('#generate').disabled=true;
  try{
   const savedAnswers=new Map([...$('#preflight-content').querySelectorAll('.material-answer')].map(field=>[field.dataset.chapterId+'\n'+field.dataset.ask,field.value]));
   $('#preflight-content').replaceChildren();
   const projectId=selected;
   if(pendingSubsections&&chosen.some(id=>!pendingSubsections[id]))throw Error('小节改写范围与章节不一致，请重新选择');
   await post(endpoint('preflight'),{chapter_ids:chosen,model_id:selectedModel(),...(pendingSubsections?{subsections:pendingSubsections,include_descendants:$('#rewrite-include-descendants')?.checked!==false}:{})});
   let state;
   do {
    state=await api(`/api/projects/${projectId}`);
    current=state;render(state);
    if(state.busy)await new Promise(resolve=>setTimeout(resolve,1200));
   } while(state.busy);
   if(state.error)throw new Error(state.error);
   if(!state.preflight_result){notify(state.message||'资料检查已停止');return;}
   const plans=state.preflight_result.plans;
   const requests=plans.flatMap(p=>p.requests.map(item=>({...item,chapter_id:p.chapter_id,chapter:p.chapter})));
   const needsInput=requests.length>0||plans.some(p=>!p.can_draft_now);
   if(needsInput){
    materialsPlan={chapter:'本次所选章节',requests,can_draft_now:plans.every(p=>p.can_draft_now),note:plans.map(p=>p.note).filter(Boolean).join('；'),baseVersion:current.report_version};
    const panel=$('#preflight-content');panel.replaceChildren(el('h3','生成前检查发现以下资料需求'));if(pendingSubsections)panel.append(el('p','本次仅修改：'+Object.values(pendingSubsections).flat().join('、'),'muted'));
    panel.append(el('p','可逐项填写已核实的信息，也可以稍后上传材料；暂时无法提供的内容会留在报告待核查清单中。'+(materialsPlan.note?' 检查说明：'+materialsPlan.note:''),'muted'));
    if(!requests.length)panel.append(el('p','模型判断现有依据不足以支撑完整编写，但未能列出具体材料项。你可以返回补充项目资料，或暂时跳过并生成可审阅草稿。','error'));
    for(const item of requests){const card=el('article',undefined,'material-request');card.append(el('strong','【'+item.priority+'】'+item.chapter+' · '+item.subheading),el('p',item.ask),el('small','需要包含：'+item.include),el('small','用途：'+item.reason));if(item.examples.length)card.append(el('small','可上传：'+item.examples.join('、')));const answer=el('textarea');answer.className='material-answer';answer.dataset.chapterId=item.chapter_id;answer.dataset.ask=item.ask;answer.value=savedAnswers.get(item.chapter_id+'\n'+item.ask)||'';answer.rows=2;answer.maxLength=2000;answer.placeholder='填写已核实的信息；没有资料可留空并选择暂时跳过。';card.append(answer);panel.append(card);}
    $('#preflight-dialog').showModal();return;
   }
  } finally {preflightBusy=false;$('#generate').disabled=Boolean(current?.busy);}
 }
 preflightApproved=false;
 await saveFacts();
 const answers={};for(const field of document.querySelectorAll('#preflight-content .material-answer, #materials-advisor .material-answer'))if(field.value.trim()){const id=field.dataset.chapterId;if(!chosen.includes(id))throw new Error('补充答复属于其他章节，请先选中对应章节或清空答复');(answers[id]??=[]).push('需要补充的事项：'+field.dataset.ask+'\n用户答复（仍需依据核验）：'+field.value.trim());}
 const supplement_answers=Object.fromEntries(Object.entries(answers).map(([id,items])=>[id,items.join('\n\n')]));
 if(Object.values(supplement_answers).reduce((sum,value)=>sum+value.length,0)>8000)throw new Error('补充内容总计超过 8000 字，请精简后继续');
 const prompt=chosen.length===1?(chapterPrompts[chosen[0]]||''):'';
 await post(endpoint('generate'),{use_llm:useLlm,model_id:selectedModel(),...(pendingSubsections?{subsections:pendingSubsections,include_descendants:$('#rewrite-include-descendants')?.checked!==false,base_version:current.report_version}:{}),instructions:[$('#instructions').value.trim(),prompt].filter(Boolean).join('\n\n'),...(Object.keys(supplement_answers).length?{supplement_answers}:{}),...($('#generation-scope').value==='selected'?{chapter_ids:chosen}:{})});
 pendingSubsections=null;$('#preflight-dialog').close();await refresh();
};
$('#preflight-cancel').onclick=()=>{$('#preflight-dialog').close();preflightApproved=false;pendingSubsections=null;};
$('#preflight-continue').onclick=async()=>{try{preflightApproved=true;$('#preflight-dialog').close();await launchGeneration();}catch(error){preflightApproved=false;notify(error.message);}};
$('#preflight-skip').onclick=async()=>{try{for(const field of $('#preflight-content').querySelectorAll('.material-answer'))field.value='';preflightApproved=true;$('#preflight-dialog').close();await launchGeneration();}catch(error){preflightApproved=false;notify(error.message);}};
let kbEditingId='';
const kbFields=['category','title','content','source','source_url','applicability','version','effective_from','effective_to','validity_status'];
function kbPayload(){return Object.fromEntries(kbFields.map(key=>[key,$('#kb-'+key.replaceAll('_','-')).value.trim()]));}
function kbFill(record){kbEditingId=record?.id||'';for(const key of kbFields){const control=$('#kb-'+key.replaceAll('_','-'));control.value=record?.[key]||(key==='category'?(control.options[0]?.value||''):key==='validity_status'?($('#kb-category').value==='regulation'?'unknown':'not_applicable'):'');}$('#kb-editing').textContent=kbEditingId?'正在编辑：'+record.title+' · v'+record.revision+'。保存后会生成新修订并退回待审核。':'新建内容会先保存为“待审核”，不会用于报告生成。';$('#kb-save').textContent=kbEditingId?'保存新修订':'保存待审核条目';}
function kbStatusLabel(status){return {draft:'待审核',approved:'审核通过',retired:'已停用'}[status]||status;}
async function loadKnowledge(){const data=await api('/api/knowledge');$('#kb-category').replaceChildren();for(const [key,label] of Object.entries(data.categories)){const opt=el('option',label);opt.value=key;$('#kb-category').append(opt);}$('#kb-count').textContent=`${data.records.length} 条 · ${data.records.filter(r=>r.status==='approved').length} 条可检索`;$('#kb-records').replaceChildren();if(!data.records.length){$('#kb-records').append(el('p','知识库还没有条目。请录入经核验的知识并审核后，才会进入报告检索。','empty-small'));return;}for(const record of data.records){const card=el('article',undefined,'evidence-item');card.append(el('strong',data.categories[record.category]+' · '+record.title+' · '+kbStatusLabel(record.status)));card.append(el('p',(record.content||'').slice(0,520)+(record.content.length>520?'…':'')));card.append(el('small',['来源：'+record.source,record.version?'版本：'+record.version:'',record.applicability?'适用范围：'+record.applicability:'',record.effective_from?'生效：'+record.effective_from:'',record.effective_to?'失效：'+record.effective_to:'',record.reviewed_by?'审核人：'+record.reviewed_by:''].filter(Boolean).join(' · ')));card.append(el('small','修订 v'+record.revision+' · '+record.updated_at));const actions=el('div',undefined,'paragraph-actions');actions.append(button('编辑',()=>{kbFill(record);$('#kb-category').closest('section').scrollIntoView({behavior:'smooth',block:'start'});$('#kb-title').focus({preventScroll:true});notify('已载入条目，请在上方表单中修改并保存。');}));if(record.status!=='approved')actions.append(button('审核通过',async()=>{const reviewer=prompt('请输入审核人姓名（请确认来源、适用范围和有效期）');if(!reviewer?.trim())return;await post('/api/knowledge/'+record.id+'/status',{status:'approved',reviewed_by:reviewer.trim()});await loadKnowledge();notify('条目已审核通过并加入知识检索');}));if(record.status!=='retired')actions.append(button('停用',async()=>{if(!confirm('停用后将不再参与检索，历史版本会保留。确定继续？'))return;await post('/api/knowledge/'+record.id+'/status',{status:'retired'});await loadKnowledge();}));if(record.status==='retired')actions.append(button('恢复为待审核',async()=>{await post('/api/knowledge/'+record.id+'/status',{status:'draft'});await loadKnowledge();}));card.append(actions);$('#kb-records').append(card);}}
$('#kb-save').onclick=async()=>{try{const payload=kbPayload();const path=kbEditingId?'/api/knowledge/'+kbEditingId+'/update':'/api/knowledge';await post(path,payload);kbFill(null);$('#kb-message').textContent='已保存为待审核条目；请核对内容、来源、适用范围和有效期后再批准。';$('#kb-message').classList.remove('hidden');await loadKnowledge();}catch(error){notify(error.message);}};
$('#kb-clear').onclick=()=>{kbFill(null);$('#kb-message').classList.add('hidden');};
$('#kb-category').onchange=()=>{$('#kb-validity-status').value=$('#kb-category').value==='regulation'?'unknown':'not_applicable';};
$('#kb-search').onclick=async()=>{try{const query=$('#kb-query').value.trim();const result=await api('/api/knowledge/search?q='+encodeURIComponent(query)+'&limit=12');$('#kb-search-results').replaceChildren();$('#kb-search-meta').textContent='检索方式：'+({hybrid_qdrant_rrf:'关键词 + 语义向量 + RRF 融合',keyword_fallback:'关键词回退（语义索引未就绪）',empty:'知识库暂无已审核条目'}[result.retrieval_mode]||result.retrieval_mode)+' · 仅审核通过、当前有效的知识参与。';if(!result.results.length)$('#kb-search-results').append(el('p','没有找到可用的已审核条目。','empty-small'));for(const item of result.results){const card=el('div',undefined,'evidence-item');card.append(el('strong',item.source+' · '+item.locator),el('p',item.text),el('small',['适用范围：'+(item.applicability||'未注明'),'来源：'+(item.source_document||'未注明'),'有效状态：'+(item.validity_status||'未注明'),item.effective_from?'生效：'+item.effective_from:'',item.effective_to?'失效：'+item.effective_to:'','审核人：'+(item.reviewed_by||'未记录')].filter(Boolean).join(' · ')));if(item.source_url){const link=el('a','打开原始来源');link.href=item.source_url;link.target='_blank';link.rel='noopener noreferrer';card.append(link);}$('#kb-search-results').append(card);}}catch(error){notify(error.message);}};
$('#kb-query').onkeydown=event=>{if(event.key==='Enter'){event.preventDefault();$('#kb-search').click();}};
let measureEditingId='';
function clearMeasureForm(){measureEditingId='';for(const id of ['measure-source-file','measure-source-locator','measure-recommendation','measure-response','measure-reviewer'])$('#'+id).value='';$('#measure-disposition').value='pending';$('#measure-section').value=(template?.headings||[]).find(h=>h.level===1&&h.text.includes('采纳'))?.text||'';$('#measure-editing').textContent='每条决定项必须能回溯到原建议；已采纳项需填写具体设计落实内容。';$('#measure-save').textContent='保存建议';}
function fillMeasureForm(item){measureEditingId=item.id;$('#measure-source-file').value=item.source_file;$('#measure-source-locator').value=item.source_locator;$('#measure-recommendation').value=item.recommendation;$('#measure-disposition').value=item.disposition;$('#measure-response').value=item.design_response;$('#measure-section').value=item.report_section;$('#measure-reviewer').value=item.reviewed_by;$('#measure-editing').textContent='正在编辑该建议，当前修订 v'+item.revision+'；保存后会保留旧版本记录。';$('#measure-save').textContent='保存修订';}
async function loadMeasures(){if(!selected||!$('#measure-list'))return;try{const result=await api(endpoint('measures'));$('#measure-list').replaceChildren();if(!result.items.length){$('#measure-list').append(el('p','尚无建议条目。可以手工添加，或将安全条件综合分析报告标记为对应资料类型后抽取候选。','empty-small'));return;}for(const item of result.items){const card=el('article',undefined,'evidence-item');card.append(el('strong','['+({pending:'待确认',adopted:'采纳',partial:'部分采纳',not_adopted:'未采纳',not_applicable:'不适用'}[item.disposition]||item.disposition)+'] '+item.recommendation),el('p','来源：'+item.source_file+' · '+item.source_locator),el('small','设计落实/理由：'+(item.design_response||'待填写')+' · 报告位置：'+(item.report_section||'未指定')+' · 确认人：'+(item.reviewed_by||'待确认')));card.append(button('编辑',()=>fillMeasureForm(item)));$('#measure-list').append(card);}}catch(error){if(!/项目不存在/.test(error.message))notify(error.message);}}
$('#measure-save').onclick=async()=>{try{const payload={...(measureEditingId?{id:measureEditingId}:{}),recommendation:$('#measure-recommendation').value,source_file:$('#measure-source-file').value,source_locator:$('#measure-source-locator').value,source_evidence_id:'',disposition:$('#measure-disposition').value,design_response:$('#measure-response').value,report_section:$('#measure-section').value,reviewed_by:$('#measure-reviewer').value};await post(endpoint('measures'),payload);clearMeasureForm();dirtyLedgers.delete('measures');await loadMeasures();notify('安全建议已保存');}catch(error){notify(error.message);}};
$('#measure-clear').onclick=()=>{clearMeasureForm();dirtyLedgers.delete('measures');};
$('#extract-measures').onclick=async()=>{if(!selectedModel()){openModelSettings();notify('先选择模型以抽取待核对的建议候选');return;}const button=$('#extract-measures');button.disabled=true;try{const result=await post(endpoint('measures'),{operation:'extract',model_id:selectedModel()});await loadMeasures();notify('已新增 '+result.count+' 条待确认建议候选，请逐条核对原文和出处');}catch(error){notify(error.message);}finally{button.disabled=false;}};
const selectProjectWithMeasures=selectProject;
selectProject=async function(id){await selectProjectWithMeasures(id);await loadMeasures();};

// Professionally reviewed calculation records are auditable evidence, never model-computed values.
let calculationEditingId='';
const calcTextFields=['title','source_rule','rule_version','rule_clause','rule_validity_status','rule_checked_date','formula','steps','result','result_unit','assumptions','reviewer','review_note','report_section'];
function addCalculationInputRow(row={}){const box=el('div',undefined,'calc-input-row');for(const [key,placeholder] of [['name','参数名称'],['value','数值或判定内容'],['unit','单位/类别'],['source_file','来源文件'],['source_locator','页码/段落/表格行'],['evidence_id','证据 ID（可选）']]){const input=el('input');input.className='calc-input-'+key;input.placeholder=placeholder;input.value=row[key]||'';input.setAttribute('aria-label',placeholder);box.append(input);}box.append(button('移除',()=>box.remove(),'secondary'));$('#calc-inputs').append(box);}
function clearCalculationForm(){calculationEditingId='';for(const key of calcTextFields)$('#calc-'+key.replaceAll('_','-')).value='';$('#calc-rule-validity-status').value='unknown';$('#calc-kind').value='hazard_identification';$('#calc-status').value='draft';$('#calc-inputs').replaceChildren();addCalculationInputRow();$('#calc-editing').textContent='人工记录或使用上方辅助计算工具后，请逐项核验依据、输入和结果。';$('#calc-save').textContent='保存计算记录';}
function fillCalculationForm(item){calculationEditingId=item.id;$('#calc-kind').value=item.kind;$('#calc-status').value=item.status;for(const key of calcTextFields)$('#calc-'+key.replaceAll('_','-')).value=item[key]||'';$('#calc-inputs').replaceChildren();for(const row of item.inputs)addCalculationInputRow(row);if(!item.inputs.length)addCalculationInputRow();$('#calc-editing').textContent='正在编辑记录，修订 v'+item.revision+'；保存将保留历史。';$('#calc-save').textContent='保存修订';$('#calculations-card').scrollIntoView({behavior:'smooth',block:'start'});}
async function loadCalculations(){if(!selected||!$('#calc-list'))return;try{const data=await api(endpoint('calculations'));$('#calc-list').replaceChildren();if(!data.items.length){$('#calc-list').append(el('p','尚无分析或计算记录。可以先建立待复核记录；复核通过后才能作为报告证据。','empty-small'));return;}const stateLabel={draft:'待复核',reviewed:'专业复核通过',rejected:'复核不通过'};for(const item of data.items){const card=el('article',undefined,'evidence-item');card.append(el('strong','['+(stateLabel[item.status]||item.status)+'] '+(data.kinds[item.kind]||item.kind)+' · '+item.title));card.append(el('p','依据：'+(item.source_rule||'待填写')+' '+(item.rule_version||'')+' '+(item.rule_clause||'')));card.append(el('p','公式/方法：'+(item.formula||'待专业人员填写')+'；结果：'+(item.result||'待复核')+' '+(item.result_unit||'')));card.append(el('small','输入 '+item.inputs.length+' 项 · 复核人：'+(item.reviewer||'未填写')+' · 报告章节：'+(item.report_section||'未指定')+' · 修订 v'+item.revision));card.append(button('编辑',()=>fillCalculationForm(item)));$('#calc-list').append(card);}}catch(error){if(!/项目不存在/.test(error.message))notify(error.message);}}
$('#calc-add-input').onclick=()=>addCalculationInputRow();
$('#calc-clear').onclick=()=>{clearCalculationForm();dirtyLedgers.delete('calculations');};
$('#calc-save').onclick=async()=>{try{const inputs=[...$('#calc-inputs').querySelectorAll('.calc-input-row')].map(row=>Object.fromEntries(['name','value','unit','source_file','source_locator','evidence_id'].map(key=>[key,row.querySelector('.calc-input-'+key).value.trim()]))).filter(row=>Object.values(row).some(Boolean));const payload={...(calculationEditingId?{id:calculationEditingId}:{}),kind:$('#calc-kind').value,status:$('#calc-status').value,inputs,...Object.fromEntries(calcTextFields.map(key=>[key,$('#calc-'+key.replaceAll('_','-')).value.trim()]))};await post(endpoint('calculations'),payload);clearCalculationForm();dirtyLedgers.delete('calculations');await loadCalculations();notify('专业分析/计算记录已保存');}catch(error){notify(error.message);}};
const selectProjectWithCalculations=selectProject;
selectProject=async function(id){await selectProjectWithCalculations(id);await loadCalculations();};
if($('#calc-inputs')&&!$('#calc-inputs').children.length)addCalculationInputRow();
function addMajorMaterialRow(item={}){const row=el('div',undefined,'major-material-row');for(const [key,placeholder] of [['name','化学品名称（已核对分类）'],['quantity_t','实际存在量 q（t）'],['quantity_source_file','q 来源文件'],['quantity_source_locator','q 来源位置'],['critical_t','临界量 Q（t）'],['critical_source_file','Q 来源标准/文件'],['critical_source_locator','Q 表号/条款']]){const input=el('input');input.className='major-'+key;input.placeholder=placeholder;input.value=item[key]||'';input.setAttribute('aria-label',placeholder);row.append(input);}row.append(button('移除',()=>row.remove()));$('#major-materials').append(row);}
if($('#major-materials')&&!$('#major-materials').children.length)addMajorMaterialRow();
$('#major-add-material').onclick=()=>addMajorMaterialRow();
$('#major-calculate').onclick=async()=>{const button=$('#major-calculate');button.disabled=true;$('#major-result').classList.add('hidden');try{const materials=[...$('#major-materials').querySelectorAll('.major-material-row')].map(row=>Object.fromEntries(['name','quantity_t','quantity_source_file','quantity_source_locator','critical_t','critical_source_file','critical_source_locator'].map(key=>[key,row.querySelector('.major-'+key).value.trim()])));const result=await post(endpoint('calculations'),{operation:'calculate_major_hazard',unit_name:$('#major-unit-name').value.trim(),unit_source_file:$('#major-unit-source').value.trim(),unit_source_locator:$('#major-unit-locator').value.trim(),materials});fillCalculationForm(result.item);$('#major-result').textContent='已计算 S = '+result.calculation.indicator+'。'+result.calculation.statement+'。记录已保存为“待复核”；请核对单元、物质适用性、临界量来源和最大存在量口径，再由专业人员填写复核信息并决定是否通过。';$('#major-result').classList.remove('hidden');await loadCalculations();}catch(error){notify(error.message);}finally{button.disabled=false;}};

// Each calculator creates a draft record; the reviewer must confirm inputs and rule applicability.
function calculatorField(label, placeholder='') {const wrapper=el('label',label);const input=el('input');input.placeholder=placeholder;input.setAttribute('aria-label',label);wrapper.append(input);return {wrapper,input};}
function sourcedControls(title, unit){const box=el('div',undefined,'calculator-source');const value=calculatorField(title+'（'+unit+'）','输入数值');const source=calculatorField(title+'来源文件','文件或标准名称');const locator=calculatorField(title+'来源位置','页码、表号或条款');box.append(value.wrapper,source.wrapper,locator.wrapper);return {box,read:()=>({value:value.input.value.trim(),source_file:source.input.value.trim(),source_locator:locator.input.value.trim()})};}
function createCalculator(title, note, build){const details=el('details',undefined,'extra-tools calculator');details.append(el('summary',title),el('p',note,'muted'));build(details);$('#major-hazard-calculator').after(details);}
function showCalculationResult(details, result){let message=details.querySelector('.calculator-result');if(!message){message=el('div',undefined,'inline-notice calculator-result');message.setAttribute('role','status');details.append(message);}message.textContent='计算结果：'+result.calculation.result+' '+result.calculation.result_unit+'。已保存为待复核记录；请核验依据、输入和适用条件。';fillCalculationForm(result.item);loadCalculations();}
createCalculator('计算消防用水量（单个火灾场景）','输入同一建筑、同一场景中经确认同时作用的各系统流量和持续时间。系统不自动选择适用系统或确定消防水池最终容积。',details=>{
 const name=calculatorField('建筑或火灾场景名称');details.append(name.wrapper);const list=el('div',undefined,'calculator-systems');details.append(list);
 function addRow(){const row=el('div',undefined,'calculator-system');const system=calculatorField('消防系统名称','例如室外消火栓');const flow=sourcedControls('设计流量','L/s');const duration=sourcedControls('火灾持续时间','h');row.append(system.wrapper,flow.box,duration.box,button('移除此系统',()=>row.remove()));row.read=()=>({name:system.input.value.trim(),flow:flow.read(),duration:duration.read()});list.append(row);}
 addRow();details.append(button('＋ 添加同时作用的系统',addRow));details.append(button('计算并保存待复核',async()=>{const result=await post(endpoint('calculations'),{operation:'calculate_fire_water',name:name.input.value.trim(),systems:[...list.children].map(row=>row.read())});showCalculationResult(details,result);},'primary'));
});
createCalculator('计算厂房泄压面积','仅适用于专业人员确认可采用 A = 10CV^(2/3) 的厂房计算段。容积、泄压比和长径比分段等条件应先核对。',details=>{
 const name=calculatorField('厂房或计算段名称');const volume=sourcedControls('厂房计算段容积 V','m³');const coefficient=sourcedControls('泄压比 C','m²/m³');details.append(name.wrapper,volume.box,coefficient.box);details.append(button('计算并保存待复核',async()=>{const result=await post(endpoint('calculations'),{operation:'calculate_pressure_relief',name:name.input.value.trim(),volume:volume.read(),coefficient:coefficient.read()});showCalculationResult(details,result);},'primary'));
});

createCalculator('距离差值辅助计算','仅比较人工确认的两个距离，不自动选择防火间距条款，也不判断合规。请核验对象、测量方式、适用条件及依据版本。',details=>{
 const name=calculatorField('比较对象');const actual=sourcedControls('实测或图示距离','m');const reference=sourcedControls('人工选定的参考距离','m');details.append(name.wrapper,actual.box,reference.box);details.append(button('计算差值并保存待复核',async()=>{const result=await post(endpoint('calculations'),{operation:'compare_distance',name:name.input.value.trim(),actual:actual.read(),reference:reference.read()});showCalculationResult(details,result);},'primary'));
});

// Keep unsaved project-specific ledger inputs from leaking into another project.
const dirtyLedgers=new Set();
for(const [selector,key] of [['#measures-card','measures'],['#calculations-card','calculations']]){
 const panel=$(selector);for(const event of ['input','change'])panel.addEventListener(event,()=>dirtyLedgers.add(key));
}
const selectProjectWithLedgerGuard=selectProject;
selectProject=async function(id){
 const old=selected;if(id!==old&&dirtyLedgers.size&&!confirm('安全措施或计算表单尚未保存，切换项目将清空表单。是否继续？'))return;
 await selectProjectWithLedgerGuard(id);
 if(selected!==old){clearMeasureForm();clearCalculationForm();document.querySelectorAll('#major-hazard-calculator input, .calculator input').forEach(input=>input.value='');document.querySelectorAll('.calculator-result').forEach(node=>node.remove());$('#major-result').classList.add('hidden');dirtyLedgers.clear();}
};

// Report-specific professional records are manually reviewed, versioned project evidence.
const professionalPanel=el('section',undefined,'card');
professionalPanel.id='professional-card';
professionalPanel.innerHTML=`<div class="card-heading"><div><span class="section-number">专业</span><h2>专业工作记录</h2></div></div>
<p class="section-description">按当前报告类型记录专业分析、核查或应急准备。请填写来源位置并由专业人员复核；只有复核通过的记录参与对应章节编写。类别是工作提示，是否适用由专业人员判断。</p>
<div class="settings-grid"><label>工作类别<select id="pro-kind"></select></label><label>标题<input id="pro-title" maxlength="200"></label></div>
<label>工作内容、过程及结论<textarea id="pro-content" rows="4" maxlength="8000" placeholder="写明对象、过程、适用条件、结果及尚待核实事项"></textarea></label><div id="pro-detail-fields" class="settings-grid"></div>
<div class="settings-grid"><label>来源文件<input id="pro-source_file" maxlength="300"></label><label>页码、段落、图号或记录位置<input id="pro-source_locator" maxlength="300"></label><label>对应主章节编号<input id="pro-report_section" maxlength="20" placeholder="例如 4"></label><label>复核状态<select id="pro-status"><option value="draft">待复核</option><option value="reviewed">专业复核通过</option><option value="rejected">复核不通过</option></select></label><label>专业复核人<input id="pro-reviewer" maxlength="120"></label></div>
<label>复核说明<textarea id="pro-review_note" rows="2" maxlength="2000"></textarea></label><div class="card-actions"><p id="pro-editing" class="muted">新建记录会保留来源及历史修订，复核状态由专业人员决定。</p><div><button type="button" id="pro-clear" class="secondary">清空</button> <button type="button" id="pro-save" class="primary">保存记录</button></div></div><div id="pro-list"></div>`;
$('#measures-card').before(professionalPanel);
let professionalId='', professionalDirty=false, professionalKinds={}, professionalSchemas={}, professionalDetailsByKind={}, previousProfessionalKind='';
const professionalFields=['kind','title','content','source_file','source_locator','report_section','status','reviewer','review_note'];
function renderProfessionalFields(values={}){const container=$('#pro-detail-fields');container.replaceChildren();for(const field of professionalSchemas[$('#pro-kind').value]||[]){const label=el('label',field.label+(field.required?'（复核必填）':''));const input=el(field.options?'select':'textarea');input.className='pro-detail';input.dataset.key=field.key;input.setAttribute('aria-label',field.label);if(field.options){const empty=el('option','请选择');empty.value='';input.append(empty);for(const choice of field.options){const option=el('option',choice);option.value=choice;input.append(option);}}else{input.rows=2;input.maxLength=2000;}input.value=values[field.key]||'';label.append(input);container.append(label);}}
function clearProfessional(){professionalId='';professionalDirty=false;professionalDetailsByKind={};previousProfessionalKind=$('#pro-kind').value;for(const key of professionalFields)if(!['kind','status'].includes(key))$('#pro-'+key).value='';$('#pro-status').value='draft';$('#pro-editing').textContent='新建记录会保留来源及历史修订，复核状态由专业人员决定。';if($('#pro-kind').value)$('#pro-report_section').value=professionalKinds[$('#pro-kind').value]?.[1]||'';renderProfessionalFields();}
professionalPanel.addEventListener('input',()=>professionalDirty=true);
professionalPanel.addEventListener('change',()=>professionalDirty=true);
$('#pro-kind').onchange=()=>{if(previousProfessionalKind)professionalDetailsByKind[previousProfessionalKind]=Object.fromEntries([...$('#pro-detail-fields').querySelectorAll('.pro-detail')].map(field=>[field.dataset.key,field.value]));previousProfessionalKind=$('#pro-kind').value;$('#pro-report_section').value=professionalKinds[previousProfessionalKind]?.[1]||'';renderProfessionalFields(professionalDetailsByKind[previousProfessionalKind]||{});};
async function loadProfessional(){if(!selected)return;try{const data=await api(endpoint('professional'));professionalKinds=data.kinds;professionalSchemas=data.schemas||{};const kind=$('#pro-kind');const chosen=kind.value;kind.replaceChildren();for(const [id,[label]] of Object.entries(data.kinds)){const option=el('option',label);option.value=id;kind.append(option);}if(data.kinds[chosen])kind.value=chosen;if(!professionalId&&!professionalDirty){previousProfessionalKind=kind.value;renderProfessionalFields(professionalDetailsByKind[kind.value]||{});}if(!professionalId&&!professionalDirty)$('#pro-report_section').value=data.kinds[kind.value]?.[1]||'';const list=$('#pro-list');list.replaceChildren();if(!data.items.length)list.append(el('p','尚无专业记录，请按项目实际情况添加并复核。','empty-small'));for(const item of data.items){const card=el('article',undefined,'evidence-item');card.append(el('strong','['+({draft:'待复核',reviewed:'复核通过',rejected:'复核不通过'}[item.status]||item.status)+'] '+(data.kinds[item.kind]?.[0]||item.kind)+' · '+item.title),el('p','来源：'+item.source_file+' · '+item.source_locator),el('small','章节 '+item.report_section+' · 复核人：'+(item.reviewer||'未填写')+' · 修订 v'+item.revision));card.append(button('编辑',()=>{professionalId=item.id;for(const key of professionalFields)$('#pro-'+key).value=item[key]||'';professionalDetailsByKind={[item.kind]:item.details||{}};previousProfessionalKind=item.kind;renderProfessionalFields(item.details||{});professionalDirty=false;$('#pro-editing').textContent='正在编辑修订 v'+item.revision+'，保存后保留历史版本。';professionalPanel.scrollIntoView({behavior:'smooth',block:'start'});}));list.append(card);}}catch(error){notify(error.message);}}
$('#pro-clear').onclick=clearProfessional;
$('#pro-save').onclick=async()=>{try{const payload=Object.fromEntries(professionalFields.map(key=>[key,$('#pro-'+key).value.trim()]));payload.details=Object.fromEntries([...$('#pro-detail-fields').querySelectorAll('.pro-detail')].map(field=>[field.dataset.key,field.value.trim()]));if(professionalId)payload.id=professionalId;const saved=await post(endpoint('professional'),payload);clearProfessional();await loadProfessional();await refresh();notify(payload.status==='reviewed'&&saved.item.status==='draft'?'记录内容有修改，已退回待复核；请核对后再次确认。':'专业记录已保存，请按需更新对应章节');}catch(error){notify(error.message);}};
const selectProjectWithProfessional=selectProject;
selectProject=async function(id){const old=selected;if(id!==old&&professionalDirty&&!confirm('专业工作记录尚未保存，切换项目将清空表单，是否继续？'))return;await selectProjectWithProfessional(id);if(selected!==old){clearProfessional();await loadProfessional();}};
window.addEventListener('beforeunload',e=>{if(professionalDirty){e.preventDefault();e.returnValue='';}});

// Local separated corpora and human-labelled retrieval checks.
const ragPanel=el('section',undefined,'card');ragPanel.id='rag-workbench';
ragPanel.innerHTML=`<div class="card-heading"><h2>检索评测</h2></div>
<p class="section-description">公司项目库仅检索当前项目资料；公共知识库仅检索已审核且符合有效期条件的条目。当前为本地原型，尚无多人账号和项目权限控制。此处用于检索测评，不生成回答；请在上方使用知识问答。</p>
<div class="settings-grid"><label>检索范围<select id="rag-scope"><option value="project">公司项目库 · 当前项目</option><option value="public">公共专业知识库</option></select></label><label>评测返回数量 K（1–20）<input id="rag-k" type="number" min="1" max="20" value="5"></label></div>
<label>检索问题<textarea id="rag-query" rows="2" placeholder="例如：项目涉及哪些危险化学品？"></textarea></label>
<div class="card-actions"><button type="button" id="rag-search" class="secondary">检索候选（最多 20 条）</button></div><p class="muted">勾选人工确认的相关证据，可更换问题继续寻找漏掉的相关证据；也可以在下方手工填写证据 ID。最后将问题改回要评测的问题，再计算指标。</p><div id="rag-results"></div>
<label>人工标注的相关证据 ID（每行一个）<textarea id="rag-labels" rows="4" placeholder="先检索并勾选相关证据；可以继续检索其他问题补充漏掉的证据"></textarea></label>
<div class="card-actions"><button type="button" id="rag-clear" class="secondary">清空标注</button><button type="button" id="rag-evaluate" class="primary">计算当前问题的指标</button></div><div id="rag-metrics" class="inline-notice hidden"></div><div class="card-actions"><button type="button" id="rag-add-case" class="secondary">保存本题到本次评测</button><button type="button" id="rag-export" class="secondary">下载本次评测 JSON</button></div><p id="rag-case-summary" class="muted">尚未保存测试题；页面关闭后未下载的结果不会保留。</p><p class="muted">Precision@K = 命中标注数 ÷ K；Recall@K = 命中标注数 ÷ 全部已标注相关证据数。标注不完整会使结果失真；本功能测检索，不等于报告事实正确率。</p>`;
$('#view-knowledge').prepend(ragPanel);
let ragProject='', ragLastEvaluation=null, ragCases=[];
function clearRagLabels(){ragLastEvaluation=null;$('#rag-labels').value='';$('#rag-results').replaceChildren();$('#rag-metrics').classList.add('hidden');}
$('#rag-scope').onchange=clearRagLabels;
$('#rag-clear').onclick=clearRagLabels;
function ragLabels(){return [...new Set($('#rag-labels').value.split(/\s+/).map(x=>x.trim()).filter(Boolean))];}
function renderRagResults(data){const box=$('#rag-results');box.replaceChildren();box.append(el('p','检索方式：'+({hybrid_qdrant_rrf:'关键词 + 本地向量 + 融合排序',keyword_fallback:'关键词回退',empty:'知识库为空'}[data.retrieval_mode]||data.retrieval_mode)+(data.warning?'；'+data.warning:''),'muted'));if(!data.results.length)box.append(el('p','没有检索到内容。','empty-small'));for(const item of data.results){const label=el('label',undefined,'evidence-item');const check=el('input');check.type='checkbox';check.checked=ragLabels().includes(item.id);check.onchange=()=>{const ids=new Set(ragLabels());if(check.checked)ids.add(item.id);else ids.delete(item.id);$('#rag-labels').value=[...ids].join('\n');};label.append(check,el('strong',' '+item.source+' · '+item.locator),el('small','证据 ID：'+item.id),el('p',item.text));box.append(label);}}
async function runRag(operation){if(!selected)throw Error('请先选择项目');if(ragProject!==selected){clearRagLabels();ragProject=selected;}const query=$('#rag-query').value.trim();const k=Number($('#rag-k').value);const payload={operation,scope:$('#rag-scope').value,query,limit:operation==='search'?20:k};if(operation==='evaluate')payload.relevant_ids=ragLabels();const data=await post(endpoint('rag-test'),payload);renderRagResults(data);const display=$('#rag-metrics');display.classList.toggle('hidden',!data.metrics);if(data.metrics){const m=data.metrics;ragLastEvaluation={query,scope:payload.scope,k,relevant_ids:payload.relevant_ids,metrics:m,retrieval_mode:data.retrieval_mode,project_id:selected,evaluated_at:new Date().toISOString()};display.textContent=`Precision@${k} ${(m.precision_at_k*100).toFixed(1)}% · Recall@${k} ${(m.recall_at_k*100).toFixed(1)}% · 命中 ${m.hit_count}/${m.relevant_count} 个已标注证据 · 返回 ${m.returned_count} 条。未命中 ID：${m.unretrieved_relevant_ids.join('、')||'无'}。`;}}
$('#rag-search').onclick=()=>runRag('search').catch(e=>notify(e.message));
$('#rag-evaluate').onclick=()=>runRag('evaluate').catch(e=>notify(e.message));
function showRagCaseSummary(){const scope=$('#rag-scope').value;const k=Number($('#rag-k').value);const cases=ragCases.filter(x=>x.scope===scope&&x.k===k);const avg=key=>cases.reduce((sum,x)=>sum+x.metrics[key],0)/cases.length;$('#rag-case-summary').textContent=cases.length?`当前范围已保存 ${cases.length} 题；宏平均 Precision@K ${(avg('precision_at_k')*100).toFixed(1)}%，Recall@K ${(avg('recall_at_k')*100).toFixed(1)}%。仅供人工标注完整的测试集参考。`:'尚未保存测试题；页面关闭后未下载的结果不会保留。';}
$('#rag-add-case').onclick=()=>{if(!ragLastEvaluation){notify('请先计算当前问题的指标');return;}const c=ragLastEvaluation;const index=ragCases.findIndex(x=>x.scope===c.scope&&x.query===c.query&&x.k===c.k);if(index<0)ragCases.push(c);else ragCases[index]=c;showRagCaseSummary();notify('已保存本题到本次评测');};
$('#rag-export').onclick=()=>{if(!ragCases.length){notify('请先保存至少一道测试题');return;}const blob=new Blob([JSON.stringify({format_version:1,project_id:selected,cases:ragCases},null,2)],{type:'application/json'});const url=URL.createObjectURL(blob);const a=el('a');a.href=url;a.download='rag-evaluation.json';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);};
$('#rag-scope').onchange=()=>{clearRagLabels();showRagCaseSummary();};$('#rag-k').onchange=showRagCaseSummary;
const selectProjectWithRag=selectProject;
selectProject=async function(id){const old=selected;await selectProjectWithRag(id);if(old!==selected){clearRagLabels();ragCases=[];ragProject=selected;showRagCaseSummary();}};

const publicImport=el('section',undefined,'card');
publicImport.innerHTML=`<div class="card-heading"><h2>导入公共资料</h2></div><p class="section-description">仅导入有权使用的公开法规、标准和专业资料。文本会拆分为待审核条目，确认来源、版本和适用范围后逐条审核；法规还需人工核验现行状态。不要在这里上传公司私密项目文件。单文件最多 20 MB、100 个文本块；扫描件需先 OCR。</p><div class="settings-grid"><label>知识分类<select id="public-import-category"><option value="regulation">法律法规与标准</option><option value="chemical">危险物料</option><option value="hazard">危险有害因素</option><option value="analysis_rule">分析规则与计算方法</option><option value="safety_measure">安全措施</option><option value="report_rule">报告编制规则</option><option value="case">历史案例</option></select></label><label>选择公开资料<input id="public-import-file" type="file" accept=".docx,.pdf,.txt,.md,.csv"></label></div><button type="button" id="public-import-submit" class="primary">导入为待审核条目</button><div id="public-import-result" class="inline-notice hidden"></div>`;
$('#view-knowledge').prepend(publicImport);
$('#public-import-submit').onclick=async()=>{const control=$('#public-import-submit');try{const file=$('#public-import-file').files[0];if(!file)throw Error('请先选择公开资料');control.disabled=true;const data=await api('/api/knowledge/import?filename='+encodeURIComponent(file.name)+'&category='+encodeURIComponent($('#public-import-category').value),{method:'POST',headers:{'Content-Type':'application/octet-stream'},body:file});const result=$('#public-import-result');result.textContent='已导入 '+data.count+' 条待审核内容。'+(data.warnings.length?'解析提示：'+data.warnings.join('；'):'请核对来源和适用范围后审核。');result.classList.remove('hidden');$('#public-import-file').value='';await loadKnowledge();}catch(error){notify(error.message);}finally{control.disabled=false;}};


// Evidence-grounded knowledge questions, distinct from retrieval evaluation.
const qaPanel=el('section',undefined,'card');qaPanel.id='knowledge-qa';
qaPanel.innerHTML=`<div class="qa-heading"><span class="qa-icon" aria-hidden="true">✦</span><div><span class="qa-kicker">KNOWLEDGE ASSISTANT</span><h2>知识问答</h2><p>提出问题，获取结合资料整理的回答。</p></div></div><p class="section-description">公共知识使用审核通过且符合有效期条件的内容。回答后可展开查看来源。</p><div class="settings-grid"><label>知识范围<select id="qa-scope"><option value="public">公共专业知识库</option><option value="project">公司项目库 · 当前项目</option></select></label><label>回答模型<select id="qa-model"></select></label></div><p id="qa-provider" class="muted"></p><label>问题<textarea id="qa-question" rows="3" maxlength="500" placeholder="例如：资料中列出了哪些重大事故隐患情形？"></textarea></label><div class="card-actions"><button type="button" id="qa-ask" class="primary">检索并回答</button><button type="button" id="qa-stop" class="secondary hidden">停止回答</button></div><div id="qa-result" aria-live="polite"></div>`;
$('#view-knowledge').prepend(qaPanel);
let qaSignature='';
function syncQaModels(){const items=modelSettings?.models||[];const sig=JSON.stringify(items.map(m=>[m.id,m.name,m.model,m.base_url]));if(sig!==qaSignature){const select=$('#qa-model'),old=select.value;select.replaceChildren();if(!items.length){const option=el('option','请先配置模型');option.value='';select.append(option);}for(const m of items){const option=el('option',m.name+' · '+m.model);option.value=m.id;select.append(option);}if(items.some(m=>m.id===old))select.value=old;else if(items.some(m=>m.id===selectedModel()))select.value=selectedModel();qaSignature=sig;}const m=items.find(x=>x.id===$('#qa-model').value);let host='未配置';try{if(m)host=new URL(m.base_url).host;}catch{}$('#qa-provider').textContent='模型服务：'+host+'。提问和检索到的片段将发送至该服务；本机模型也需确认地址。';}
function showQa(project){syncQaModels();const busy=project.busy&&project.current_operation==='knowledge-qa';$('#qa-ask').disabled=project.busy;$('#qa-stop').classList.toggle('hidden',!busy);$('#qa-stop').disabled=project.cancel_requested;const box=$('#qa-result');box.replaceChildren();if(busy){box.append(el('p',project.message,'muted'));return;}const result=project.qa_result;if(!result)return;box.append(el('div','✦  知识助手','qa-answer-label'),el('p',result.question,'qa-user-question'));const ids=new Map((result.sources||[]).map((x,i)=>[x.id,i+1]));for(const para of result.paragraphs||[])box.append(el('p',para.text+' '+para.evidence_ids.map(id=>'['+ids.get(id)+']').join(''),'qa-answer-paragraph'));if(result.missing?.length){box.append(el('strong','资料不足或待确认'));for(const item of result.missing)box.append(el('p','• '+item));}if(result.sources?.length){const details=el('details');details.append(el('summary','查看发送给模型的引用片段（'+result.sources.length+'）'));result.sources.forEach((src,i)=>{const item=el('article',undefined,'evidence-item');item.append(el('strong','['+(i+1)+'] '+src.source+' · '+src.locator),el('p',src.text||''));details.append(item);});box.append(details);}if(result.sent_evidence?.length){const sent=el('details');sent.append(el('summary','查看本次发送给模型的全部资料片段（'+result.sent_evidence.length+'）'));for(const src of result.sent_evidence){const item=el('article',undefined,'evidence-item');item.append(el('strong',src.source+' · '+src.locator),el('p',src.text));sent.append(item);}box.append(sent);}box.append(el('p','引用表示模型选择了对应资料，并不保证内容获得支持；请专业人员核对原文及版本。','muted'));}
const renderWithKnowledgeQa=render;render=function(project){renderWithKnowledgeQa(project);showQa(project);};
$('#qa-model').onchange=syncQaModels;
$('#qa-ask').onclick=async()=>{try{syncQaModels();const question=$('#qa-question').value.trim(),model=$('#qa-model').value,scope=$('#qa-scope').value;if(!question)throw Error('请填写问题');if(!model){openModelSettings();throw Error('请先配置并选择模型');}const m=modelSettings.models.find(x=>x.id===model);let host='所选模型服务';try{host=new URL(m.base_url).host;}catch{}if(!confirm('问题和检索到的'+(scope==='project'?'当前项目资料':'公共知识')+'片段将发送至 '+host+'。片段经本机切分和筛选，但仍可能包含姓名、电话或其他敏感信息，不保证自动脱敏；请确认资料适合发送。是否继续？'))return;await post(endpoint('knowledge-qa'),{question,scope,model_id:model});await refresh();}catch(e){notify(e.message);}};
$('#qa-stop').onclick=async()=>{try{await post(endpoint('cancel'));await refresh();}catch(e){notify(e.message);}};


