for(const [name,links] of navGroups){const group=el('div',undefined,'task-nav-group');group.append(el('div',name,'task-nav-heading'));for(const [label,target,anchor] of links){const b=button('',async()=>{if(!selected){notify('请先创建或选择项目');return;}const previousView=view;showView(target);if(target==='knowledge'&&previousView!=='knowledge')await loadKnowledge();let element=$(anchor);if(element?.classList.contains('hidden')&&anchor==='#measures-card'){notify('当前报告类型不使用安全措施承接台账，已跳转到分析计算');element=$('#calculations-card');}if(element){if(element.tagName==='DETAILS')element.open=true;const outer=element.closest('details');if(outer)outer.open=true;const section=element.closest('.card')||element;section.scrollIntoView({behavior:'smooth',block:'start'});}taskButtons.forEach(item=>item.classList.toggle('is-current',item===b));},'task-nav-link');b.append(el('span','·','task-nav-dot'),el('span',label));b.dataset.targetView=target;group.append(b);taskButtons.push(b);}sidebarNav.append(group);}
