const ragAdvanced=el('details',undefined,'card advanced-tools');ragAdvanced.id='rag-advanced';ragAdvanced.append(el('summary','高级工具：检索评测与调试'));ragPanel.before(ragAdvanced);ragAdvanced.append(ragPanel);ragPanel.classList.add('advanced-inner');
