const figureSection=$('#asset-list').closest('section');figureSection.id='figure-card';const guide=el('div',undefined,'figure-guide');guide.append(el('strong','图片如何进入报告？'),el('p','① 上传图片或 PDF  ② 选择章节末尾或指定段落后，勾选“放入报告”，填写图题与页码并保存  ③ 重新生成报告，或在已有草稿中保存一次章节后下载 Word。'),el('small','如原段落被修改或删除，图件会暂放在文末并在核对清单提示，请重新选择位置。DWG/DXF 需先导出为 PDF 或图片。'));figureSection.querySelector('.section-description').after(guide);

// A chapter-oriented editor built on the existing save and generation handlers.
const editorRenderBeforeWorkspace=renderEditor;
renderEditor=function(){
  editorRenderBeforeWorkspace();
  if(!report)return;
  let layout=$('#chapter-workspace');
  if(!layout){
    layout=el('div',undefined,'chapter-workspace');layout.id='chapter-workspace';
    const nav=el('nav',undefined,'chapter-navigation');nav.setAttribute('aria-label','报告章节');nav.append(el('div','报告目录','workspace-column-title'));const list=el('div');list.id='chapter-navigation-list';nav.append(list);
    const paper=el('div',undefined,'chapter-paper');paper.append(el('div','REPORT EDITOR  /  章节正文','paper-kicker'));const title=el('h3');title.id='chapter-paper-title';paper.append(title);
    const assistant=el('div',undefined,'chapter-assistant');assistant.append(el('div','✦  编写助手','workspace-column-title'),el('p','填写修改要求后，可勾选小节局部改写，也可选择重写整章。','muted'));
    const anchor=$('#paragraph-editor');anchor.before(layout);layout.append(nav,paper,assistant);
    for(const id of ['chapter-generation-warning','paragraph-editor','table-editor']){const node=$('#'+id);if(node)paper.append(node);}
    for(const id of ['chapter-prompt-box','materials-advisor']){const node=$('#'+id);if(node)assistant.append(node);}
    const actions=el('div',undefined,'assistant-actions');actions.append(button('重写整章',()=>$('#rewrite-current').click(),'secondary'),button('检查所需资料',()=>$('#ask-materials').click(),'secondary'));assistant.append(actions);
    for(const node of [$('#chapter-review').closest('details'),$('#agent-trace-panel'),$('#chapter-source-review'),$('#chapter-grounded-review')])if(node)assistant.append(node);
  }
  $('#chapter-paper-title').textContent=report.sections[currentChapter].title;
  const list=$('#chapter-navigation-list');list.replaceChildren();
  report.sections.forEach((section,index)=>{const item=button(section.title,()=>{if(index===currentChapter)return;$('#editor-chapter').value=String(index);$('#editor-chapter').dispatchEvent(new Event('change'));},'chapter-navigation-item');item.classList.toggle('active',index===currentChapter);item.setAttribute('aria-current',index===currentChapter?'true':'false');list.append(item);});
};

