// A report template is kept separate from factual project documents.
let templateCandidate=null;
function renderTemplateSettings(project){
 let panel=$('#report-template-settings');
 if(!panel){
  panel=el('details',undefined,'evidence-panel');panel.id='report-template-settings';
  panel.append(el('summary','报告模板 · 上传并确认目录与格式'));
  panel.append(el('p','上传 .docx 后先预览目录，可修改标题再确认应用。生成采用目录，Word 采用首个分节的纸张、页边距及正文/标题样式。复杂封面、多分节、页眉页脚和原表格布局暂不复刻；模板中的原项目内容不作为事实资料。','muted'));
  const state=el('p');state.id='report-template-state';panel.append(state);
  const input=el('input');input.type='file';input.accept='.docx';input.id='report-template-file';input.setAttribute('aria-label','选择报告模板 Word 文件');panel.append(input);
  const preview=el('div');preview.id='report-template-preview';preview.className='hidden';
  const note=el('p');note.id='report-template-note';preview.append(note);
  const outline=el('textarea');outline.id='report-template-outline';outline.rows=12;outline.setAttribute('aria-label','确认模板目录，每行一个标题');preview.append(outline);
  const apply=button('确认应用模板',async()=>{
   if(!templateCandidate)return;
   const headings=outline.value.split('\n').map(x=>x.trim()).filter(Boolean).map(text=>{const n=text.match(/^\d+(?:\.\d+)*/);return {text,level:n?n[0].split('.').length:0};});
   if(!confirm('应用该目录和格式？下一次生成将按新目录建立草稿，已有版本保留。请确认模板适用于当前报告类型。'))return;
   apply.disabled=true;try{await post(endpoint('template-apply'),{sha256:templateCandidate.sha256,headings});templateCandidate=null;preview.classList.add('hidden');input.value='';await refresh();buildChapterChecks();notify('模板已应用，请选择新目录中的章节生成');}finally{apply.disabled=!!current?.busy;}
  },'primary');apply.id='report-template-apply';preview.append(apply);panel.append(preview);
  input.onchange=async()=>{const file=input.files[0];if(!file)return;templateCandidate=null;preview.classList.add('hidden');input.disabled=true;try{const result=await api(endpoint('template-upload')+'?name='+encodeURIComponent(file.name),{method:'POST',headers:{'Content-Type':'application/octet-stream'},body:file});templateCandidate=result.candidate;outline.value=templateCandidate.headings.map(h=>h.text).join('\n');note.textContent='已识别 '+templateCandidate.headings.length+' 个标题。请核对并修正目录；格式只参考样式，不带入正文和原图。';preview.classList.remove('hidden');}catch(error){notify(error.message);}finally{input.disabled=!!current?.busy;}};
  const reset=button('恢复默认模板',async()=>{if(!confirm('恢复当前报告类型的默认目录和格式？已有报告版本保留。'))return;await post(endpoint('template-reset'),{});templateCandidate=null;preview.classList.add('hidden');await refresh();buildChapterChecks();});reset.id='report-template-reset';panel.append(reset);
  $('#dropzone').before(panel);
 }
 $('#report-template-state').textContent=project.report_template?'当前模板：'+project.report_template.name+' · '+project.report_template.headings.length+' 个标题':'当前采用系统默认模板';
 for(const id of ['report-template-file','report-template-apply','report-template-reset'])$('#'+id).disabled=!!project.busy;
 $('#report-template-reset').classList.toggle('hidden',!project.report_template);
 if(panel.dataset.projectId!==project.id){templateCandidate=null;$('#report-template-preview').classList.add('hidden');$('#report-template-file').value='';panel.dataset.projectId=project.id;}
}

let templateBodyData=null;
async function loadTemplateBody(){
 const requestedProject=selected;const data=await api(endpoint('report-template-content'));if(requestedProject!==selected)return;
 templateBodyData=data;let box=$('#template-body-panel');
 if(!box){box=el('details',undefined,'evidence-panel');box.id='template-body-panel';box.dataset.key=selected+':'+(current?.report_template?.sha256||'');$('#report-template-settings').append(box);}
 const oldFilter=box.querySelector('select')?.value||'';box.replaceChildren();box.open=true;
 box.append(el('summary','模板正文复用审核（'+data.blocks.length+' 段）'),el('p','默认仅参考，不进入生成。请逐段核对专业表述及适用性；可编辑为通用表述后批准原文复用。带厂名、参数、规范或结论的段落应结合项目改写，项目事实须另有资料支持。','muted'));
 if(!data.blocks.length){box.append(el('p','未提取到正文候选。旧模板请重新上传并应用；章节标题需使用 Word 标题样式。'));return;}
 const search=el('input');search.type='search';search.placeholder='查找模板段落，例如：触电、火灾';search.setAttribute('aria-label','搜索模板正文');
 const filter=el('select');filter.setAttribute('aria-label','按章节筛选模板段落');const all=el('option','全部章节');all.value='';filter.append(all);
 for(const heading of [...new Set(data.blocks.map(b=>b.heading))]){const opt=el('option',heading);opt.value=heading;filter.append(opt);}filter.value=oldFilter;
 const list=el('div');let page=0;const pager=el('div',undefined,'file-bulk-toolbar');const previous=button('上一页',()=>{page--;draw();list.scrollIntoView({behavior:'smooth',block:'start'});});const next=button('下一页',()=>{page++;draw();list.scrollIntoView({behavior:'smooth',block:'start'});});const count=el('span');pager.append(previous,count,next);box.append(filter,search,list,pager);
 function draw(){
  const blocks=data.blocks.filter(b=>(!filter.value||b.heading===filter.value)&&(!search.value.trim()||b.text.includes(search.value.trim())||b.heading.includes(search.value.trim())));const total=Math.max(1,Math.ceil(blocks.length/12));page=Math.max(0,Math.min(page,total-1));count.textContent=(page+1)+' / '+total+' 页 · '+blocks.length+' 段';previous.disabled=page===0;next.disabled=page+1>=total;list.replaceChildren();
  for(const b of blocks.slice(page*12,(page+1)*12)){
   const card=el('div',undefined,'template-body-card');card.append(el('strong',(b.source_file||'报告模板')+' · '+(b.source_heading||b.heading)+' · '+b.locator));
   const target=el('select');target.setAttribute('aria-label',b.id+'目标标题');target.append(new Option('请选择本报告的目标章节或小节',''));for(const h of data.headings)target.append(new Option(h.text,h.text));target.value=b.heading;card.append(target);
   const original=el('details');original.append(el('summary','查看模板原文'),el('p',b.original_text));card.append(original);
   const text=el('textarea');text.rows=5;text.value=b.text;text.maxLength=12000;text.setAttribute('aria-label',b.id+'复用正文');card.append(text);
   const mode=el('select');mode.setAttribute('aria-label',b.id+'复用方式');for(const [value,label] of [['reference','仅作参考（不进入生成）'],['direct','审核后原文复用'],['adapt','结合本项目改写'],['exclude','不使用']]){const opt=el('option',label);opt.value=value;opt.selected=b.decision===value;mode.append(opt);}card.append(mode);
   if(b.risks?.length)card.append(el('p','需核对：'+b.risks.join('、'),'conflict'));
   const applicability=el('textarea');applicability.rows=2;applicability.value=b.applicability||'';applicability.maxLength=1000;applicability.placeholder='适用对象、工况和条件，例如：本项目存在低压配电及用电设备，作为通用触电机理分析，不认定现场已存在缺陷。';applicability.setAttribute('aria-label',b.id+'适用条件');card.append(applicability);
   const label=el('label');const confirmed=el('input');confirmed.type='checkbox';label.append(confirmed,document.createTextNode(' 已核对专业准确性和当前项目适用条件'));card.append(label);
   card.append(el('small',b.reviewed?'已审核；修改后需再次勾选确认并保存':'尚未批准用于正文'));
   const save=button('保存本段复用设置',async()=>{save.disabled=true;try{await post(endpoint('template-content-review'),{id:b.id,expected_revision:data.content_revision,heading:target.value,text:text.value,decision:mode.value,applicability:applicability.value,applicability_confirmed:confirmed.checked});await loadTemplateBody();await refresh();notify('本段设置已保存；按需更新对应章节');}catch(error){save.disabled=false;throw error;}},'secondary');save.disabled=!!current?.busy;card.append(save);list.append(card);
  }
 }
 filter.onchange=()=>{page=0;draw();};search.oninput=()=>{page=0;draw();};draw();
}
const renderTemplateBeforeBody=renderTemplateSettings;
renderTemplateSettings=function(project){
 renderTemplateBeforeBody(project);let control=$('#manage-template-body');if(!control){control=button('审核参考正文与模板复用',()=>loadTemplateBody(),'secondary');control.id='manage-template-body';$('#report-template-settings').append(control);}
 control.disabled=!!project.busy||!(project.report_template||project.reference_reuse_count);
 const panel=$('#template-body-panel');const key=project.id+':'+(project.report_template?.sha256||'');if(panel&&panel.dataset.key!==key){panel.remove();templateBodyData=null;}if($('#template-body-panel'))$('#template-body-panel').dataset.key=key;
};

function renderChapterWorkflow(){
 if(!report?.sections?.length)return;const section=report.sections[currentChapter],id=sectionId(section);const status=report.chapter_workflow?.[id]||{locked:false,status:'待确认',warnings:[]};
 let bar=$('#chapter-workflow-controls');if(!bar){bar=el('div',undefined,'chapter-workflow-controls');bar.id='chapter-workflow-controls';$('#chapter-paper-title').after(bar);}bar.replaceChildren();
 for(const [index,item] of [...($('#chapter-navigation-list')?.children||[])].entries()){const entry=report.sections[index];if(entry)item.textContent=entry.title+' · '+(report.chapter_workflow?.[sectionId(entry)]?.status||'待确认');}
 bar.append(el('strong',status.status));for(const warning of status.warnings||[])bar.append(el('p',warning,'conflict'));
 async function approve(locked){if(factsDirty)await saveFacts();if(editorDirty)await saveSection();await post(endpoint('chapter-approval'),{base_version:current.report_version,chapter_id:id,locked});loadedVersion=null;await refresh();}
 const lock=button(status.locked?'解锁编辑':'确认本章并锁定',()=>approve(!status.locked),'secondary');lock.disabled=!!current.busy;bar.append(lock);
 if(status.locked&&status.warnings?.length){const reconfirm=button('复核后重新确认',()=>approve(true),'secondary');reconfirm.disabled=!!current.busy;bar.append(reconfirm);}
 async function move(offset){if(editorDirty)await saveSection();const order=report.sections.map(sectionId);const index=order.indexOf(id),other=index+offset;if(other<0||other>=order.length)return;[order[index],order[other]]=[order[other],order[index]];await post(endpoint('chapter-order'),{base_version:current.report_version,order});currentChapter=other;loadedVersion=null;await refresh();}
 const up=button('↑ 上移',()=>move(-1),'secondary'),down=button('↓ 下移',()=>move(1),'secondary');up.disabled=current.busy||currentChapter===0;down.disabled=current.busy||currentChapter===report.sections.length-1;bar.append(up,down);
 bar.append(el('small','排序保留原章节编号；组稿前会检查编号顺序。'));
 for(const input of document.querySelectorAll('#paragraph-editor textarea,#paragraph-editor select,#paragraph-editor button,#table-editor textarea,#table-editor button'))input.disabled=!!current.busy||status.locked;
 for(const key of ['save-section','add-paragraph','rewrite-current']){const node=$('#'+key);if(node)node.disabled=!!current.busy||status.locked;}
 for(const box of $('#chapter-checks').querySelectorAll('input')){const locked=report.chapter_workflow?.[box.value]?.locked;box.disabled=!!current.busy||!!locked;if(locked)box.checked=false;}
}
const renderEditorBeforeWorkflow=renderEditor;
renderEditor=function(){renderEditorBeforeWorkflow();renderChapterWorkflow();};
async function inspectAssembly(){
 let box=$('#assembly-panel');if(!box){box=el('dialog');box.id='assembly-panel';box.setAttribute('aria-label','最终组稿检查');document.body.append(box);}
 if(box.open)return;
 const close=button('关闭',()=>box.close()),heading=el('h2','最终组稿检查'),status=el('p','正在检查章节、来源、附件与确认状态，请稍候……');status.setAttribute('role','status');status.setAttribute('aria-live','polite');box.replaceChildren(heading,close,status);box.showModal();
 const control=$('#inspect-assembly');if(control)control.disabled=true;
 try{
  if(editorDirty)await saveSection();const data=await post(endpoint('assembly-check'),{base_version:current.report_version});
  status.textContent=data.can_assemble?'检查完成，可以组装总稿。':'检查完成：有 '+data.blockers.length+' 项需要处理，暂不能生成正式总稿。';box.append(el('p',data.note));
  for(const [title,items] of [['需先处理的问题',data.blockers],['待专业审核提示',data.warnings]]){const group=el('details');group.open=!!items.length;group.append(el('summary',title+'（'+items.length+'）'));const list=el('ul');for(const item of items)list.append(el('li',item));group.append(list);box.append(group);}
  const assemble=button('按当前顺序组装总稿',async()=>{
   if(data.warnings.length&&!confirm('已查看组稿提示，并确认保留待专业审核事项继续组稿？'))return;
   assemble.disabled=true;close.disabled=true;box.oncancel=event=>event.preventDefault();status.textContent='正在组装章节、附入原件并计算目录页码，请勿重复提交……';
   try{const result=await post(endpoint('assemble'),{base_version:current.report_version,acknowledge_warnings:true});loadedVersion=null;status.textContent='总稿已保存为新版本，可下载；本次未调用模型。';const links=el('div',undefined,'assembly-downloads');links.append(download('report.docx','下载总稿 Word',result.version),download('review.html','查看核对清单',result.version));if(result.pdf_ready)links.append(download('report.pdf','下载分页 PDF',result.version));box.append(links);try{await refresh();}catch(refreshError){status.textContent='总稿已保存，可使用下方链接下载。页面刷新未完成：'+refreshError.message;}}
   catch(error){status.textContent='本次组装未完成：'+error.message+'。已有版本保留。';assemble.disabled=false;}
   finally{close.disabled=false;box.oncancel=null;}
  },'primary');assemble.disabled=!data.can_assemble||current.busy;box.append(assemble);
 }catch(error){status.textContent='组稿检查未完成：'+error.message;box.append(button('重新检查',()=>{box.close();return inspectAssembly();}));}
 finally{if(control)control.disabled=!!current.busy||!current.has_report;}
}
const renderBeforeAssembly=render;
render=function(project){renderBeforeAssembly(project);if(report)renderChapterWorkflow();let control=$('#inspect-assembly');if(!control){control=button('检查并组装总稿',inspectAssembly,'secondary');control.id='inspect-assembly';$('#editor-card .card-heading').append(control);}control.disabled=!!project.busy||!project.has_report;};
